const LUNAR_BASE_DATE = new Date(1900, 0, 31); // 农历 1900 正月初一对应的公历日

/** 农历年总天数 */
function lYearDays(y: number): number {
  let sum = 348;
  for (let i = 0x8000; i > 0x8; i >>= 1) {
    sum += lunarInfo[y - 1900] & i ? 1 : 0;
  }
  return sum + leapDays(y);
}

/** 闰月月份（0 表示无闰月） */
function leapMonth(y: number): number {
  return lunarInfo[y - 1900] & 0xf;
}

/** 闰月天数 */
function leapDays(y: number): number {
  if (leapMonth(y)) {
    return lunarInfo[y - 1900] & 0x10000 ? 30 : 29;
  }
  return 0;
}

/** 某月天数（m 为 1-12，非闰月） */
function monthDays(y: number, m: number): number {
  return lunarInfo[y - 1900] & (0x10000 >> m) ? 30 : 29;
}

export interface LunarDate {
  lunarYear: number;
  lunarMonth: number; // 1-12
  lunarDay: number; // 1-30
  isLeap: boolean; // 是否闰月
  monthName: string; // 正月/二月/.../冬月/腊月
  dayName: string; // 初一/十五/廿三...
}

const LUNAR_MONTH_NAMES = ['正月', '二月', '三月', '四月', '五月', '六月', '七月', '八月', '九月', '十月', '冬月', '腊月'];
const LUNAR_DAY_NUMS = ['日', '一', '二', '三', '四', '五', '六', '七', '八', '九', '十'];

/** 农历日序号 → 中文名 */
export function getLunarDayName(day: number): string {
  if (day === 10) return '初十';
  if (day === 20) return '二十';
  if (day === 30) return '三十';
  const tens = Math.floor(day / 10);
  const ones = day % 10;
  const prefix = ['初', '十', '廿', '卅'][tens];
  return prefix + LUNAR_DAY_NUMS[ones];
}

/**
 * 公历 → 农历。经典 jjonline 算法：以 1900-01-31 为基，按 lunarInfo 逐月扣减天数。
 * 范围 1900-2100；超界返回 null。
 */
export function solarToLunar(year: number, month: number, day: number): LunarDate | null {
  if (year < 1900 || year > 2100) return null;
  let offset = Math.round((new Date(year, month - 1, day).getTime() - LUNAR_BASE_DATE.getTime()) / 86400000);
  if (offset < 0) return null;

  let i: number;
  let temp = 0;
  let lunarYear = 1900;
  for (i = 1900; i < 2101 && offset > 0; i++) {
    temp = lYearDays(i);
    offset -= temp;
  }
  if (offset < 0) {
    offset += temp;
    i--;
  }
  lunarYear = i;

  const leap = leapMonth(i);
  let isLeap = false;
  let lunarMonth = 1;
  for (i = 1; i < 13 && offset > 0; i++) {
    if (leap > 0 && i === leap + 1 && !isLeap) {
      i--;
      isLeap = true;
      temp = leapDays(lunarYear);
    } else {
      temp = monthDays(lunarYear, i);
    }
    if (isLeap && i === leap + 1) {
      isLeap = false;
    }
    offset -= temp;
  }
  if (offset === 0 && leap > 0 && i === leap + 1) {
    if (isLeap) {
      isLeap = false;
    } else {
      isLeap = true;
      i--;
    }
  }
  if (offset < 0) {
    offset += temp;
    i--;
  }
  lunarMonth = i;
  const lunarDay = offset + 1;

  return {
    lunarYear,
    lunarMonth,
    lunarDay,
    isLeap,
    monthName: LUNAR_MONTH_NAMES[lunarMonth - 1] || `第${lunarMonth}月`,
    dayName: getLunarDayName(lunarDay),
  };
}

/* ------------------------------------------------------------------ *
 * 2. 儒略日 + 日干支
 * ------------------------------------------------------------------ */

const TIAN_GAN = ['甲', '乙', '丙', '丁', '戊', '己', '庚', '辛', '壬', '癸'];
const DI_ZHI = ['子', '丑', '寅', '卯', '辰', '巳', '午', '未', '申', '酉', '戌', '亥'];

/** 公历日期 → 正午儒略日（整数）。格里高利历，适用于 1582 后。 */
function toJDN(year: number, month: number, day: number): number {
  let y = year;
  let m = month;
  if (m <= 2) {
    m += 12;
    y -= 1;
  }
  const a = Math.floor(y / 100);
  const b = 2 - a + Math.floor(a / 4);
  return Math.floor(365.25 * (y + 4716)) + Math.floor(30.6001 * (m + 1)) + day + b - 1524;
}

/** 东八区(北京)偏移，用于把 UTC 儒略日对齐到北京时间所辖的公历日 */
const BJ_OFFSET = 8 / 24;

/** 儒略日（含小数）→ 公历 {year,month,day} */
function jdToGregorian(jd: number): { year: number; month: number; day: number } {
  jd += 0.5;
  const z = Math.floor(jd);
  const a = Math.floor((z - 1867216.25) / 36524.25);
  const A = z < 2299161 ? z : z + 1 + a - Math.floor(a / 4);
  const B = A + 1524;
  const C = Math.floor((B - 122.1) / 365.25);
  const D = Math.floor(365.25 * C);
  const E = Math.floor((B - D) / 30.6001);
  const day = B - D - Math.floor(30.6001 * E);
  const month = E < 14 ? E - 1 : E - 13;
  const year = month > 2 ? C - 4716 : C - 4715;
  return { year, month, day };
}

export interface GanZhi {
  gan: string;
  zhi: string;
  ganIndex: number;
  zhiIndex: number;
}

/** 日干支。锚点：offset = 正午JDN - 11（lunar-javascript/6tail 权威实现）。 */
export function getDayGanZhi(year: number, month: number, day: number): GanZhi {
  const offset = toJDN(year, month, day) - 11;
  const ganIndex = ((offset % 10) + 10) % 10;
  const zhiIndex = ((offset % 12) + 12) % 12;
  return { gan: TIAN_GAN[ganIndex], zhi: DI_ZHI[zhiIndex], ganIndex, zhiIndex };
}

/* ------------------------------------------------------------------ *
 * 3. 节气：寿星天文公式（太阳视黄经法）精确计算
 * ------------------------------------------------------------------ */

const J2000 = 2451545.0;
const deg2rad = (d: number) => (d * Math.PI) / 180;
const norm360 = (d: number) => ((d % 360) + 360) % 360;

/** 儒略日 jd 时刻的太阳视黄经（度，0-360）。VSOP87 简化 + 章动主项。 */
function solarLongitude(jd: number): number {
  const t = (jd - J2000) / 36525.0;
  const L = 280.46646 + 36000.76983 * t + 0.0003032 * t * t; // 平黄经
  const M = 357.52911 + 35999.05029 * t - 0.0001537 * t * t; // 平近点角
  const Mr = deg2rad(M);
  // 中心差（地球轨道方程主要项）
  const C =
    (1.914602 - 0.004817 * t - 0.000014 * t * t) * Math.sin(Mr) +
    (0.019993 - 0.000101 * t) * Math.sin(2 * Mr) +
    0.000289 * Math.sin(3 * Mr);
  const theta = L + C; // 真黄经
  const omega = 125.04 - 1934.136 * t; // 月升交点黄经
  return norm360(theta - 0.00569 - 0.00478 * Math.sin(deg2rad(omega))); // 视黄经（含章动）
}

/** 求太阳黄经达到目标度数 degree 的儒略日。Newton 迭代。 */
function solarTermJD(year: number, degree: number): number {
  // 粗估：春分(degree=0)约在年内第 80 天，每 15° 约 15.218 天
  const n = (((degree / 360) * 365.2422 + 80) % 365.2422) + (year - 2000) * 365.2422;
  let jd = J2000 + n - 50;
  for (let i = 0; i < 30; i++) {
    const L = solarLongitude(jd);
    let diff = degree - L;
    diff = ((diff % 360) + 540) % 360 - 180; // 归一到 -180..180
    if (Math.abs(diff) < 1e-6) break;
    jd += diff / (360 / 365.2422); // 1 天 ≈ 0.9856°
  }
  return jd;
}

