/** 计算某公历年的全部 24 节气（含精确公历日，按北京时间） */
export function getSolarTermsForYear(year: number): SolarTermInfo[] {
  return SOLAR_TERM_DEFS.map(def => {
    const g = jdToGregorian(solarTermJD(year, def.degree) + BJ_OFFSET);
    return { name: def.name, month: g.month, day: g.day, desc: def.desc };
  });
}

/** 查找某公历日是否为节气（精确匹配，无容差） */
export function findSolarTerm(year: number, month: number, day: number): SolarTermInfo | null {
  const terms = getSolarTermsForYear(year);
  return terms.find(t => t.month === month && t.day === day) || null;
}

/** 某年某月"节令"（非中气）的公历日，用于定月支（北京时间） */
function getMonthTermDay(year: number, month: number): number {
  const def = SOLAR_TERM_DEFS.find(d => d.month === month && isJie(d.name));
  if (!def) return 15;
  const g = jdToGregorian(solarTermJD(year, def.degree) + BJ_OFFSET);
  return g.day;
}

/** 节令（定月支用）而非中气 */
function isJie(name: string): boolean {
  return ['立春', '惊蛰', '清明', '立夏', '芒种', '小暑', '立秋', '白露', '寒露', '立冬', '大雪', '小寒'].includes(name);
}

