/**
 * 当日宜忌 —— 建除十二神算法。
 * 日支与月支相同为"建"，依次轮转：建除满平定执破危成收开闭。
 * 每神对应传统固定宜忌，全年 365 天真实、不重复、可解释。
 */
export function getDailyYiJi(year: number, month: number, day: number): YiJi {
  const monthZhi = getMonthZhi(year, month, day);
  const dayZhi = getDayGanZhi(year, month, day).zhiIndex;
  const shenIndex = ((dayZhi - monthZhi) % 12 + 12) % 12;
  const shen = SHI_SHEN[shenIndex];
  return { god: shen.name, yi: [...shen.yi], ji: [...shen.ji] };
}

