/** 农历某月最后一天是几日（29 或 30） */
function lunarMonthLastDay(lunarYear: number, lunarMonth: number): number {
  return monthDays(lunarYear, lunarMonth);
}

/**
 * 查找某公历日对应的农历节日。内部先转农历再匹配。
 * day=0 的节日（除夕）匹配当月最后一天。
 */
export function findFestival(year: number, month: number, day: number): FestivalInfo | null {
  const lunar = solarToLunar(year, month, day);
  if (!lunar) return null;
  return (
    FESTIVAL_DEFS.find(f => {
      if (f.day === 0) {
        // 除夕：农历当月最后一天
        return lunar.lunarMonth === f.month && lunar.lunarDay === lunarMonthLastDay(lunar.lunarYear, lunar.lunarMonth);
      }
      return lunar.lunarMonth === f.month && lunar.lunarDay === f.day;
    }) || null
  );
}

