/**
 * 茶楼_今夜 ↔ 聊天世界书同步模块
 *
 * 聊天世界书中固定一条蓝灯条目「茶楼_今夜」：
 * - constant（蓝灯）：排期/幕次是环境状态，不言生今日是否现身须每轮告知 AI；
 * - at_depth:0 system，order 170：与黄历(200)/天象(190)/暗流(180)同层，排在最后；
 * - 不现身之日条目内容为"今夜不言生不在座"（短句，省 token），现身之日写完整幕次指令；
 * - 翻页 = 整条重写 content：与黄历同幂等机制。
 *
 * 与「不言生_{caseId}」条目的区别：
 * - 茶楼_今夜 = 今晚的排期和幕次指令（AI 该讲什么类型的故事）
 * - 不言生_{caseId} = 不言生针对某案讲过的所有故事（原话复述，持久沉淀）
 *
 * 内容由 storyteller.ts 的 getStorytellerSection 纯本地计算，不调用任何 AI API。
 */

import type { GameTime } from '../store/GameContext';
import { getStorytellerSection } from '../data/storyteller';

/** 聊天世界书条目名称（固定单条） */
const TEAHOUSE_ENTRY_NAME = '茶楼_今夜';

/** 聊天变量中记录"当前已写入的茶楼排期"的键 */
const TEAHOUSE_DATE_KEY = 'mirageTeahouseDate';

/** 蓝灯条目配置（与 almanacWorldbook 同构，仅 order 不同） */
const TEAHOUSE_ENTRY_TEMPLATE = {
  enabled: true,
  strategy: {
    type: 'constant' as const,
    keys: [] as (string | RegExp)[],
    keys_secondary: { logic: 'and_any' as const, keys: [] as (string | RegExp)[] },
    scan_depth: 'same_as_global' as const,
  },
  position: {
    type: 'at_depth' as const,
    role: 'system' as const,
    depth: 0,
    order: 170,
  },
  probability: 100,
  recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
};

/** 内容版本：模板/幕次逻辑变更时 +1，让旧聊天的条目自动重写归一 */
const TEAHOUSE_CONTENT_VERSION = 2;

/** 获取或创建聊天世界书，返回世界书名称 */
async function ensureChatWorldbook(): Promise<string | null> {
  try {
    return await getOrCreateChatWorldbook('current');
  } catch (e) {
    console.warn('[幻璃镜] 无法获取聊天世界书', e);
    return null;
  }
}

/**
 * 确保「茶楼_今夜」条目与当前游戏日期一致（幂等）。
 * 不现身之日写入短句"今夜不言生不在座"，现身之日写入完整幕次指令。
 * @returns 是否发生了写入
 */
export async function ensureTeahouseEntry(gt: GameTime): Promise<boolean> {
  const nextKey = `v${TEAHOUSE_CONTENT_VERSION}-${gt.eraYear}-${gt.month}-${gt.day}`;
  try {
    const vars = getVariables({ type: 'chat' }) as any;
    if (vars?.[TEAHOUSE_DATE_KEY] === nextKey) return false;
  } catch {
    // 读不到聊天变量时继续走写入路径：宁可重写，不可缺条
  }

  const wbName = await ensureChatWorldbook();
  if (!wbName) return false;

  const storytellerLines = getStorytellerSection(gt);
  const content = storytellerLines.length > 0
    ? storytellerLines.join('\n')
    : '<teahouse>\n今夜不言生不在座，茶楼歇业。\n</teahouse>';

  try {
    await updateWorldbookWith(wbName, wb => {
      const idx = wb.findIndex(e => e.name === TEAHOUSE_ENTRY_NAME);
      if (idx >= 0) {
        const next = [...wb];
        next[idx] = { ...next[idx], content, ...TEAHOUSE_ENTRY_TEMPLATE };
        return next;
      }
      return [...wb, { name: TEAHOUSE_ENTRY_NAME, content, ...TEAHOUSE_ENTRY_TEMPLATE }];
    });
  } catch (e) {
    console.warn('[幻璃镜] 写入茶楼条目失败', e);
    return false;
  }

  try {
    updateVariablesWith(vars => ({ ...vars, [TEAHOUSE_DATE_KEY]: nextKey }), { type: 'chat' });
  } catch {
    console.warn('[幻璃镜] 无法持久化茶楼日期键（下次仍会重写，不影响正确性）');
  }
  console.info('[幻璃镜] 茶楼条目已就绪:', nextKey);
  return true;
}
