/**
 * 昼夜天时色彩联动层 — 让场景 CG 的色温随游戏内时辰/天气轻微漂移：
 *   白昼偏暖金，夜晚压靛蓝；雨天浸青灰、雾天蒙乳白、雪天透冷玉。
 * 纯装饰叠层（pointer-events 关闭），颜色切换带长过渡，避免换景时色调跳变。
 * 层级约定：插在背景 CG 与底部墨色渐变之间（SceneBackground 内部调用）。
 */
import React from 'react';
import type { WeatherType, Season } from '../../data/weather';

/** 白昼色温表（极低透明度，只做"调温"不做遮蔽） */
const DAY_TINT: Record<WeatherType, string> = {
  '晴': 'rgba(255, 208, 130, 0.07)',
  '阴': 'rgba(88, 98, 118, 0.13)',
  '小雨': 'rgba(58, 76, 96, 0.17)',
  '大雨': 'rgba(38, 52, 72, 0.23)',
  '雾': 'rgba(185, 190, 198, 0.15)',
  '雷暴': 'rgba(28, 36, 64, 0.28)',
  '小雪': 'rgba(205, 222, 240, 0.1)',
  '大雪': 'rgba(205, 222, 240, 0.15)',
};

/** 夜晚色温表：整体下沉靛蓝 */
const NIGHT_TINT: Record<WeatherType, string> = {
  '晴': 'rgba(22, 34, 84, 0.2)',
  '阴': 'rgba(14, 22, 48, 0.26)',
  '小雨': 'rgba(8, 20, 42, 0.28)',
  '大雨': 'rgba(6, 16, 36, 0.32)',
  '雾': 'rgba(66, 80, 108, 0.18)',
  '雷暴': 'rgba(10, 14, 34, 0.34)',
  '小雪': 'rgba(56, 86, 128, 0.14)',
  '大雪': 'rgba(56, 86, 128, 0.2)',
};

/** 季节色调层：同一张 CG 随节气换"气色"（春青/夏赤/秋金/冬玉），素材无需按季重绘 */
const SEASON_TINT: Record<Season, string> = {
  spring: 'rgba(140, 210, 130, 0.05)',
  summer: 'rgba(255, 196, 84, 0.05)',
  autumn: 'rgba(224, 148, 56, 0.08)',
  winter: 'rgba(148, 184, 232, 0.07)',
};

interface EnvironmentTintProps {
  weather: WeatherType;
  isNight: boolean;
  season?: Season;
}

export const EnvironmentTint = React.memo(function EnvironmentTint({ weather, isNight, season }: EnvironmentTintProps) {
  const tint = (isNight ? NIGHT_TINT : DAY_TINT)[weather] ?? 'transparent';
  const seasonTint = season ? SEASON_TINT[season] : 'transparent';

  return (
    <>
      {/* 天时色温层：随天气/昼夜平滑过渡 */}
      <div
        className="absolute inset-0 pointer-events-none z-[5] transition-all duration-[1800ms] ease-out"
        style={{ background: tint }}
      />
      {/* 季节气色层：随节气缓变，与昼夜层叠加 */}
      <div
        className="absolute inset-0 pointer-events-none z-[5] transition-all duration-[2400ms] ease-out"
        style={{ background: seasonTint }}
      />
      {/* 夜幕渐晕：天顶靛蓝垂落、地平微沉，只在夜晚浮现 */}
      <div
        className={`absolute inset-0 pointer-events-none z-[5] bg-linear-to-b from-indigo-700/35 via-transparent to-ink-975/45 transition-opacity duration-[2200ms] ease-out ${isNight ? 'opacity-100' : 'opacity-0'}`}
      />
    </>
  );
});
