/**
 * 线索卷宗 ↔ 聊天世界书同步模块
 *
 * 每个案件在聊天世界书中是一个条目：
 * - 进行中：蓝灯（constant），插入 at_depth 深度0 system，AI 每次都能看到
 * - 结案后：绿灯（selective），带关键词，插入 after_character_definition，只在相关话题激活
 */

import type { Clue } from '../store/GameContext';

/**
 * 链条完整性检测：推论或推断所依赖的源素材中，是否有被玩家标记为伪证的推断。
 * 若有，该推论/推断的地基动摇，但不自动降级，仅在渲染时标记。
 */
export function isGroundShaken(clue: Clue, allClues: Clue[]): boolean {
  if (!clue.sourceClueIds || clue.sourceClueIds.length === 0) return false;
  for (const sid of clue.sourceClueIds) {
    const source = allClues.find(c => c.id === sid);
    if (!source) continue;
    if (source.type === 'inference' && source.status === 'false') return true;
    if (isGroundShaken(source, allClues)) return true;
  }
  return false;
}

/** 聊天世界书条目名称前缀 */
const CASE_ENTRY_PREFIX = '案件_';

/** 蓝灯条目配置（进行中） */
const ACTIVE_ENTRY_TEMPLATE = {
  enabled: true,
  strategy: {
    type: 'constant' as const,
    keys: [] as (string | RegExp)[],
    keys_secondary: { logic: 'and_any' as const, keys: [] as (string | RegExp)[] },
    scan_depth: 'same_as_global' as const,
  },
  position: {
    type: 'at_depth' as const,
    role: 'system' as const,
    depth: 0,
    order: 200,
  },
  probability: 100,
  recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
};

/** 绿灯条目配置（已结案） */
const CLOSED_ENTRY_TEMPLATE = {
  enabled: true,
  strategy: {
    type: 'selective' as const,
    keys: [] as (string | RegExp)[],
    keys_secondary: { logic: 'and_any' as const, keys: [] as (string | RegExp)[] },
    scan_depth: 'same_as_global' as const,
  },
  position: {
    type: 'after_character_definition' as const,
    role: 'system' as const,
    depth: 0,
    order: 200,
  },
  probability: 100,
  recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
};

/** 获取或创建聊天世界书，返回世界书名称 */
async function ensureChatWorldbook(): Promise<string | null> {
  try {
    const name = await getOrCreateChatWorldbook('current');
    return name;
  } catch (e) {
    console.warn('[幻璃镜] 无法获取聊天世界书', e);
    return null;
  }
}

/** 根据案件 ID 构造世界书条目名称 */
export function caseEntryName(caseId: string): string {
  return `${CASE_ENTRY_PREFIX}${caseId}`;
}

/** 截断文本用于推论的源线索回显 */
function shorten(text: string, max = 18): string {
  return text.length > max ? `${text.slice(0, max)}…` : text;
}

/** 推论轴线类型转中文 */
function deductionTypeLabel(type?: string): string {
  if (type === 'how') return '手法';
  if (type === 'why') return '动机';
  if (type === 'who') return '身份';
  return '未分轴';
}

/**
 * 将线索、推断和推论列表渲染为世界书条目的 content 文本
 *
 * 分区结构（AI 视角）：
 * - 线索：已确立事实 / 待证信息
 * - 推断：初步判断，未经证实，不得当作事实引用
 * - 推论：按手法/动机/身份分轴，玩家标记属实的视为事实，其余为待验
 * - AI专属·玩家不可见：隐藏判定及处理指令，制造戏剧反讽；地基动摇警告
 *
 * 双轨读取：分区以玩家标记 status 为主，隐藏判定 truth 仅进 AI 专属区
 */
export function renderCaseContent(
  caseName: string,
  clues: Clue[],
  isClosed: boolean,
  closingStatement?: string,
  origin?: string,
): string {
  const lines: string[] = [];
  lines.push(`【案件：${caseName}】`);
  lines.push('状态：' + (isClosed ? '已结案' : '调查中'));
  if (origin) lines.push(`案由：${origin}`);
  lines.push('');

  if (isClosed && closingStatement) {
    lines.push('结案陈词：');
    lines.push(closingStatement);
    lines.push('');
  }

  const standaloneClues = clues.filter(c => c.type === 'clue');
  const inferences = clues.filter(c => c.type === 'inference');
  const deductions = clues.filter(c => c.type === 'deduction');
  const clueTextById = new Map(clues.map(c => [c.id, c.text]));

  // 证据两区：硬证据（勘验/文书，或已坐实的软信息）＝事实；未坐实的证言/传闻＝仅作方向
  const hardClues = standaloneClues.filter(c => !c.category || c.category === '勘验' || c.category === '文书' || c.verified === true);
  const softOpen = standaloneClues.filter(c => c.category && (c.category === '证言' || c.category === '传闻') && c.verified !== true);

  if (hardClues.length > 0) {
    lines.push('线索：');
    for (const clue of hardClues) {
      lines.push(`- ${clue.category ? `[${clue.category}] ` : ''}${clue.text}`);
    }
    lines.push('');
  }

  if (softOpen.length > 0) {
    lines.push('待证信息：');
    for (const clue of softOpen) {
      lines.push(`- [${clue.category}·待证] ${clue.text}`);
    }
    lines.push('');
  }

  // 推断层
  if (inferences.length > 0) {
    lines.push('推断：');
    for (const inf of inferences) {
      const sources = (inf.sourceClueIds ?? [])
        .map(id => clueTextById.get(id))
        .filter(Boolean)
        .map(t => `「${shorten(t as string)}」`)
        .join('+');
      const statusDesc = inf.status === 'true' ? '·属实' : inf.status === 'false' ? '·伪证' : '';
      const shaken = isGroundShaken(inf, clues) ? '·地基动摇' : '';
      lines.push(`- ${sources ? `${inf.text}（由${sources}推出）` : inf.text}${statusDesc}${shaken}`);
    }
    lines.push('');
  }

  // 推论层：按手法/动机/身份分轴
  const provenDeductions = deductions.filter(d => d.status === 'true');
  const pendingDeductions = deductions.filter(d => d.status !== 'true');

  const renderDeduction = (ded: Clue) => {
    const sources = (ded.sourceClueIds ?? [])
      .map(id => clueTextById.get(id))
      .filter(Boolean)
      .map(t => `「${shorten(t as string)}」`)
      .join('+');
    const shaken = isGroundShaken(ded, clues) ? '·地基动摇' : '';
    return sources ? `${ded.text}（由${sources}推出）${shaken}` : `${ded.text}${shaken}`;
  };

  if (provenDeductions.length > 0) {
    lines.push('已证推论：');
    for (const axis of ['how', 'why', 'who'] as const) {
      const axisDeds = provenDeductions.filter(d => d.deductionType === axis);
      if (axisDeds.length > 0) {
        lines.push(`  ${deductionTypeLabel(axis)}：`);
        for (const ded of axisDeds) {
          lines.push(`  - ${renderDeduction(ded)}`);
        }
      }
    }
    const untyped = provenDeductions.filter(d => !d.deductionType);
    if (untyped.length > 0) {
      lines.push('  未分轴：');
      for (const ded of untyped) {
        lines.push(`  - ${renderDeduction(ded)}`);
      }
    }
    lines.push('');
  }

  if (pendingDeductions.length > 0) {
    lines.push('待验推论：');
    for (const axis of ['how', 'why', 'who'] as const) {
      const axisDeds = pendingDeductions.filter(d => d.deductionType === axis);
      if (axisDeds.length > 0) {
        lines.push(`  ${deductionTypeLabel(axis)}：`);
        for (const ded of axisDeds) {
          lines.push(`  - ${renderDeduction(ded)}`);
        }
      }
    }
    const untyped = pendingDeductions.filter(d => !d.deductionType);
    if (untyped.length > 0) {
      lines.push('  未分轴：');
      for (const ded of untyped) {
        lines.push(`  - ${renderDeduction(ded)}`);
      }
    }
    lines.push('');
  }

  // AI专属区：隐藏判定 + 地基动摇指令
  const hiddenDeductions = deductions.filter(d => d.truth === 'false' || d.truth === 'half');
  const hiddenInferences = inferences.filter(d => d.truth === 'false' || d.truth === 'half');
  const shakenItems = [...inferences, ...deductions].filter(c => isGroundShaken(c, clues));

  if (hiddenDeductions.length > 0 || hiddenInferences.length > 0 || shakenItems.length > 0) {
    lines.push('【AI专属·玩家不可见】');
    for (const inf of hiddenInferences) {
      if (inf.truth === 'false') {
        lines.push(`- 推断「${inf.text}」判定为假：渐进安排新线索作反证，待玩家自行推翻。`);
      } else if (inf.truth === 'half') {
        lines.push(`- 推断「${inf.text}」判定为半真：可部分印证，但须保留反转空间。`);
      }
    }
    for (const ded of hiddenDeductions) {
      if (ded.truth === 'false') {
        lines.push(`- 推论「${ded.text}」判定为假：渐进安排新线索作反证，待玩家自行推翻。`);
      } else {
        lines.push(`- 推论「${ded.text}」判定为半真：可部分印证，但须保留反转空间。`);
      }
    }
    for (const item of shakenItems) {
      const typeLabel = item.type === 'deduction' ? '推论' : '推断';
      lines.push(`- ${typeLabel}「${item.text}」地基动摇：所依推断已被标记为伪证，应安排新的验证或反证机会。`);
    }
    lines.push('');
  }

  return lines.join('\n');
}

/**
 * 为新案件创建一个蓝灯条目（upsert：已有同名条目则重写，否则追加）
 */
export async function createCaseEntry(caseId: string, caseName: string, clues: Clue[], origin?: string): Promise<boolean> {
  const wbName = await ensureChatWorldbook();
  if (!wbName) return false;

  const content = renderCaseContent(caseName, clues, false, undefined, origin);
  const entryName = caseEntryName(caseId);

  try {
    await updateWorldbookWith(wbName, wb => {
      const idx = wb.findIndex(e => e.name === entryName);
      if (idx >= 0) {
        const next = [...wb];
        next[idx] = { ...next[idx], content, ...ACTIVE_ENTRY_TEMPLATE };
        return next;
      }
      return [...wb, { name: entryName, content, ...ACTIVE_ENTRY_TEMPLATE }];
    });
    console.info(`[幻璃镜] 案件条目已创建: ${entryName}`);
    return true;
  } catch (e) {
    console.warn(`[幻璃镜] 创建案件条目失败`, e);
    return false;
  }
}

/**
 * 更新案件条目的 content（线索/推论变化时）。
 * upsert：条目不存在时（createCaseEntry 异步未完成或被手删）自动补建。
 */
export async function updateCaseEntry(caseId: string, caseName: string, clues: Clue[], isClosed: boolean, closingStatement?: string, origin?: string): Promise<void> {
  const wbName = await ensureChatWorldbook();
  if (!wbName) return;

  const entryName = caseEntryName(caseId);
  const content = renderCaseContent(caseName, clues, isClosed, closingStatement, origin);
  const template = isClosed ? CLOSED_ENTRY_TEMPLATE : ACTIVE_ENTRY_TEMPLATE;

  try {
    await updateWorldbookWith(wbName, (wb) => {
      const idx = wb.findIndex(entry => entry.name === entryName);
      if (idx >= 0) {
        const next = [...wb];
        next[idx] = { ...next[idx], content };
        return next;
      }
      return [...wb, { name: entryName, content, ...template }];
    });
  } catch (e) {
    console.warn(`[幻璃镜] 更新案件条目失败`, e);
  }
}

/**
 * 结案：将蓝灯条目改为绿灯，设置关键词，移到角色定义之后
 */
export async function closeCaseEntry(caseId: string, caseName: string, keywords: string[], clues: Clue[], closingStatement: string, origin?: string): Promise<boolean> {
  const wbName = await ensureChatWorldbook();
  if (!wbName) return false;

  const entryName = caseEntryName(caseId);
  const content = renderCaseContent(caseName, clues, true, closingStatement, origin);

  try {
    await updateWorldbookWith(wbName, (wb) => {
      return wb.map(entry => {
        if (entry.name === entryName) {
          return {
            ...entry,
            content,
            strategy: {
              ...entry.strategy,
              type: 'selective' as const,
              keys: keywords,
            },
            position: {
              ...entry.position,
              type: 'after_character_definition' as const,
              role: 'system' as const,
              depth: 0,
              order: 200,
            },
          };
        }
        return entry;
      });
    });
    console.info(`[幻璃镜] 案件已结案: ${entryName}`);
    return true;
  } catch (e) {
    console.warn(`[幻璃镜] 结案条目失败`, e);
    return false;
  }
}

/**
 * 删除案件条目
 */
export async function deleteCaseEntry(caseId: string): Promise<void> {
  const wbName = await ensureChatWorldbook();
  if (!wbName) return;

  const entryName = caseEntryName(caseId);

  try {
    await deleteWorldbookEntries(wbName, entry => entry.name === entryName);
    console.info(`[幻璃镜] 案件条目已删除: ${entryName}`);
  } catch (e) {
    console.warn(`[幻璃镜] 删除案件条目失败`, e);
  }
}
