/**
 * 幻璃镜天气引擎 — 志怪氛围的连续天气演变
 *
 * 8 种天气，分 3 大类（对应 3 种 CG 底图）：
 *   晴类（晴 CG）：晴
 *   阴类（阴 CG 底图 + 粒子区分）：阴、小雨、大雨、雾、雷暴
 *   雪类（雪 CG 底图 + 粒子区分）：小雪、大雪
 *
 * 天气随剧情推进（每条新 assistant 消息）按马尔可夫链演变：
 *   连续性优先（晴易持续、雷暴短暂），偶发突变（10% 概率，80% 温和/20% 剧烈）。
 * 不做预报（古代无预报），只记"近期天象"（过去天气日志，持久化到聊天变量）。
 * AI 正文描写的天气会回写覆盖系统天气。
 */
import { getSolarTermsForYear } from './calendarData';
import { eraYearToSolarYear, hourToShichen, getSunriseSunset, gameDayOrdinal } from './almanacNote';
/** 天气 → CG 底图三类映射 */
export function weatherToCgVariant(w) {
    switch (w) {
        case '晴': return 'sunny';
        case '阴':
        case '小雨':
        case '大雨':
        case '雾':
        case '雷暴': return 'cloudy';
        case '小雪':
        case '大雪': return 'snowy';
    }
}
/** 天气中文描述（给 AI 提示词注入用） */
const WEATHER_DESC = {
    '晴': '天朗气清，日色明丽',
    '阴': '阴云蔽日，天色晦暗',
    '小雨': '细雨如织，淅淅沥沥',
    '大雨': '大雨倾盆，雨幕如注',
    '雾': '浓雾弥漫，氤氲不散',
    '雷暴': '雷鸣电闪，风雨交加',
    '小雪': '飞雪初降，零零落落',
    '大雪': '大雪纷飞，天地素白',
};
export function getWeatherDesc(w) {
    return WEATHER_DESC[w] ?? '';
}
/** 天气 lucide 图标名（CalendarModal/GameScreen 取用） */
export const WEATHER_ICON = {
    '晴': 'Sun',
    '阴': 'Cloud',
    '小雨': 'CloudDrizzle',
    '大雨': 'CloudRain',
    '雾': 'CloudFog',
    '雷暴': 'CloudLightning',
    '小雪': 'CloudSnow',
    '大雪': 'CloudSnow',
};
/**
 * 按节气判定季节（立春/立夏/立秋/立冬分界——钦天监口径，岁首立春之前属冬）。
 * 节气公式异常时退回公历月近似（旧口径）。
 */
export function getSeason(gt) {
    const year = eraYearToSolarYear(gt.eraYear);
    try {
        const boundaries = getSolarTermsForYear(year).filter(t => ['立春', '立夏', '立秋', '立冬'].includes(t.name));
        let season = 'winter';
        for (const b of boundaries) {
            if (gt.month > b.month || (gt.month === b.month && gt.day >= b.day)) {
                season = b.name === '立春' ? 'spring' : b.name === '立夏' ? 'summer' : b.name === '立秋' ? 'autumn' : 'winter';
            }
        }
        return season;
    }
    catch {
        const m = gt.month;
        if (m >= 3 && m <= 5)
            return 'spring';
        if (m >= 6 && m <= 8)
            return 'summer';
        if (m >= 9 && m <= 11)
            return 'autumn';
        return 'winter';
    }
}
/**
 * 各季节的天气倾向概率表（归一化前为权重，不必和为 1）。
 * 设计意图：春多阴雨雾、夏多雷暴雨、秋多阴晴雾、冬多雪与晴。
 */
const SEASON_PROB = {
    spring: { '晴': 3, '阴': 4, '小雨': 4, '大雨': 2, '雾': 3, '雷暴': 1, '小雪': 0.3, '大雪': 0.1 },
    summer: { '晴': 3, '阴': 3, '小雨': 3, '大雨': 3, '雾': 1, '雷暴': 3, '小雪': 0, '大雪': 0 },
    autumn: { '晴': 4, '阴': 3, '小雨': 2, '大雨': 1, '雾': 3, '雷暴': 0.5, '小雪': 0.3, '大雪': 0.1 },
    winter: { '晴': 3, '阴': 2, '小雨': 0.5, '大雨': 0.2, '雾': 2, '雷暴': 0.1, '小雪': 4, '大雪': 3 },
};
/** 持续性因子：越大越倾向维持现状（晴/阴易持续，雷暴/大雨短暂） */
const PERSISTENCE = {
    '晴': 2.5, '阴': 2.0, '小雨': 1.2, '大雨': 0.6, '雾': 1.5, '雷暴': 0.3, '小雪': 1.5, '大雪': 1.8,
};
/** 相似性分组：温和过渡时只在此组内切换，避免晴直接跳雷暴 */
const SIMILARITY = [
    ['晴', '阴'],
    ['阴', '小雨', '雾'],
    ['小雨', '大雨'],
    ['小雪', '大雪'],
];
function similarityGroup(w) {
    return SIMILARITY.find(g => g.includes(w)) ?? [w];
}
/** 按权重表抽一个（加权随机） */
function weightedPick(table, rng) {
    const entries = Object.entries(table).filter(([, v]) => v > 0);
    const total = entries.reduce((s, [, v]) => s + v, 0);
    let r = rng() * total;
    for (const [w, v] of entries) {
        r -= v;
        if (r <= 0)
            return w;
    }
    return entries[0]?.[0] ?? '阴';
}
/** 带种子的伪随机（同楼层结果稳定，避免重渲染抖动） */
function seededRng(seed) {
    let s = seed % 233280;
    return () => {
        s = (s * 9301 + 49297) % 233280;
        return s / 233280;
    };
}
/**
 * 滚动一次天气。
 * @param prev 上一天气
 * @param gt 游戏内时间（按节气定季节）
 * @param seed 种子（建议用消息楼层号，保证同消息结果稳定）
 */
export function rollWeather(prev, gt, seed) {
    const rng = seededRng(seed * 7 + gt.month * 13 + 1);
    const season = getSeason(gt);
    const base = SEASON_PROB[season];
    // 1) 突变判定：~10% 概率发生突变
    if (rng() < 0.1) {
        const dramatic = rng() < 0.2; // 20% 剧烈突变（季节表随机），80% 温和（相似组内）
        if (dramatic) {
            return weightedPick(base, rng);
        }
        // 温和突变：在相似组内按季节权重挑一个（排除当前）
        const group = similarityGroup(prev).filter(w => w !== prev);
        if (group.length === 0)
            return prev;
        const subTable = {};
        group.forEach(w => { subTable[w] = base[w]; });
        return weightedPick(subTable, rng);
    }
    // 2) 连续性：按"持续性因子 + 季节权重"决定是否维持
    const stayWeight = PERSISTENCE[prev] * 2;
    const changeWeight = Object.entries(base)
        .filter(([w]) => w !== prev)
        .reduce((s, [, v]) => s + v, 0);
    const total = stayWeight + changeWeight;
    if (rng() * total < stayWeight) {
        return prev; // 维持
    }
    // 变化：按季节权重抽一个（排除当前），倾向于相似组
    const changeTable = {};
    Object.entries(base)
        .filter(([w]) => w !== prev)
        .forEach(([w, v]) => {
        const g = similarityGroup(prev);
        changeTable[w] = g.includes(w) ? v * 2 : v; // 相似组加权
    });
    return weightedPick(changeTable, rng);
}
/* ------------------------------------------------------------------ *
 * 天象条目内容生成（世界书「天象_当前」蓝灯条目，由 weatherWorldbook 调用）
 * ------------------------------------------------------------------ */
/**
 * 天气 → 探案效应指令（AI 叙事规则，玩家亦可知——天象人人可见）。
 * 三条通道：痕迹（雨毁雪留）、耳目（掩声/眼杂）、邪异（雾雷）。
 */
const WEATHER_EFFECTS = {
    '晴': ['晴日人多眼杂：市井查访得利；私会、隐匿、灭口难行'],
    '阴': ['天色晦暗：细小痕迹与文书字迹难辨'],
    '小雨': ['细雨渐蚀：户外痕迹渐模糊，泥路湿滑，街面冷清'],
    '大雨': ['大雨冲痕：户外足迹血迹冲毁，勘验远行受阻', '雨声掩耳：潜入、私会、灭口易行'],
    '雷暴': ['雷声掩耳：潜入、私会、灭口易行', '邪异躁动：夜行遇险大增'],
    '雾': ['大雾迷踪：方向难辨；雾中人影难辨敌我，跟踪伏击皆易行'],
    '小雪': ['初雪微寒：街面行人稀少'],
    '大雪': ['雪地留痕：足迹清晰可追；出行滞缓，路有冻馁之危'],
};
/** 今日分时段（上午6-12/下午12-18/傍晚18-21/夜间21-5） */
const WEATHER_SLOTS = ['上午', '下午', '傍晚', '夜间'];
function currentSlot(hour) {
    if (hour >= 21 || hour < 6)
        return 3;
    if (hour >= 18)
        return 2;
    if (hour >= 12)
        return 1;
    return 0;
}
/**
 * 今日分时段预报：从当前时段起按马尔可夫链前推，当日按日序数定种子（同日确定性）。
 * 注入给 AI 后，正文天气须与之一致（租借男友验证过的天气一致性强制规则）。
 */
function buildForecast(weather, gt) {
    const ordinal = gameDayOrdinal(gt);
    const cur = currentSlot(gt.hour);
    let state = weather;
    const parts = [];
    for (let si = cur; si < WEATHER_SLOTS.length; si++) {
        if (si > cur)
            state = rollWeather(state, gt, ordinal * 31 + si * 7);
        parts.push(`${WEATHER_SLOTS[si]}${state}`);
    }
    return `${parts.join(' · ')}（当前：${WEATHER_SLOTS[cur]}${weather}）`;
}
/**
 * 生成「天象_当前」条目内容（纯函数）。
 * 结构：此刻天象 → 天气效应指令 → 时辰/所在（天时地利一格）→ 近期天象记档 → 突变约定。
 * 近期天象来自 weatherLog（按变化逐条记录，末条即当前）；待 MVU 接入后可换算为真实"近几日"。
 * @param gt 游戏时间（取时辰）
 * @param location 当前所在地点（stat_data.地点.当前地点，空则省略所在行）
 */
export function buildWeatherContent(weather, gt, location, log = loadWeatherLog()) {
    const lines = [];
    lines.push('<celestial>');
    lines.push(`天气: ${weather}，${getWeatherDesc(weather)}`);
    for (const eff of WEATHER_EFFECTS[weather] ?? []) {
        lines.push(eff.replace('：', ': '));
    }
    const { sunrise, sunset } = getSunriseSunset(gt);
    const fmt = (h) => `${Math.floor(h)}时${h % 1 ? '半' : ''}`;
    lines.push(`时辰: ${hourToShichen(gt.hour)}`);
    lines.push(`日出: 约${fmt(sunrise)}；日入: 约${fmt(sunset)}`);
    if (gt.hour >= sunset || gt.hour < sunrise) {
        lines.push('禁令: 夜禁时分，坊门已闭');
    }
    if (location) {
        lines.push(`所在: ${location}`);
    }
    if (log.length > 1) {
        const history = log.slice(-6).map(e => e.weather).join(' → ');
        lines.push(`近期: ${history}（当前）`);
    }
    lines.push(`预报: ${buildForecast(weather, gt)}`);
    lines.push('</celestial>');
    return lines.join('\n');
}
/* ------------------------------------------------------------------ *
 * AI 正文天气回写
 * ------------------------------------------------------------------ */
/** 天气关键词 → 天气类型，按优先级排序（先匹配的优先，如"雷阵雨"含雷暴+小雨，取雷暴） */
const WEATHER_KEYWORDS = [
    { kw: ['雷暴', '雷电', '雷鸣', '闪电', '惊雷', '雷霆'], type: '雷暴' },
    { kw: ['大雨', '暴雨', '倾盆', '如注', '雨幕'], type: '大雨' },
    { kw: ['小雨', '细雨', '淅沥', '微雨', '雨丝'], type: '小雨' },
    { kw: ['大雪', '纷飞', '鹅毛', '素白', '雪幕'], type: '大雪' },
    { kw: ['小雪', '初雪', '飞雪', '零星'], type: '小雪' },
    { kw: ['雾', '浓雾', '氤氲', '雾气', '雾霭'], type: '雾' },
    { kw: ['阴', '阴云', '晦暗', '阴霾', '云蔽'], type: '阴' },
    { kw: ['晴', '日朗', '明丽', '日色', '天朗'], type: '晴' },
];
/**
 * 从 AI 消息文本提取天气。
 * 只扫 `<content>` 内的旁白行（非对话/心理），避免角色台词里的"雨"误判。
 */
export function extractWeatherFromText(raw) {
    // 提取 <content> 块
    const contentMatch = raw.match(/<content>([\s\S]*?)<\/content>/);
    const text = contentMatch ? contentMatch[1] : raw;
    // 逐行扫，跳过对话行（含 " 或 *内心独白*）
    const lines = text.split(/\n/);
    const narration = lines
        .filter(l => {
        const t = l.trim();
        if (!t)
            return false;
        if (t.includes(']:"'))
            return false; // 对话
        if (t.startsWith('<user>'))
            return false;
        if (t.includes('*内心') || t.includes('*独白'))
            return false;
        return true;
    })
        .join('');
    for (const { kw, type } of WEATHER_KEYWORDS) {
        if (kw.some(k => narration.includes(k)))
            return type;
    }
    return null;
}
const WEATHER_LOG_KEY = 'mirageWeatherLog';
const MAX_LOG = 30;
/** 从聊天变量读天气日志 */
export function loadWeatherLog() {
    try {
        const vars = getVariables({ type: 'chat' });
        const raw = vars?.[WEATHER_LOG_KEY];
        if (!Array.isArray(raw))
            return [];
        return raw.slice(-MAX_LOG);
    }
    catch {
        return [];
    }
}
/**
 * 追加一条天气日志并持久化。
 * @returns 更新后的日志（裁剪到最近 MAX_LOG 条）
 */
export function appendWeatherLog(entry) {
    try {
        const vars = getVariables({ type: 'chat' });
        const prev = Array.isArray(vars?.[WEATHER_LOG_KEY]) ? vars[WEATHER_LOG_KEY] : [];
        const next = [...prev, entry].slice(-MAX_LOG);
        updateVariablesWith(v => ({ ...v, [WEATHER_LOG_KEY]: next }), { type: 'chat' });
        return next;
    }
    catch {
        return [entry];
    }
}
/** 初始化默认天气（新聊天 / 无记录时），按节气季节取权重最高者 */
export function getDefaultWeather(gt) {
    const season = getSeason(gt);
    const base = SEASON_PROB[season];
    // 取该季节权重最高的
    return Object.entries(base).reduce((a, b) => (b[1] > a[1] ? b : a))[0];
}
