/**
 * 天气视觉叠层 — 移植自租借男友并裁剪适配幻璃镜
 *
 * 8 种天气按 CG 三类 + 粒子特效表现：
 *   雨 → Canvas 雨线（light/heavy）；雪 → DOM 雪花（light/heavy）；
 *   雾 → radial-gradient + motion 平移；雷暴 → 雨(heavy) + 闪电。
 * 色块滤镜按天气浓度叠加，分室外/室内两套。
 * 仅依赖 motion/react（项目已用），无 Canvas 之外的第三方。
 */

import React, { useEffect, useRef, useMemo } from 'react';
import { motion } from 'motion/react';
import type { WeatherType } from '../../data/weather';

/* ------------------------------------------------------------------ *
 * 粒子子组件（零耦合，独立）
 * ------------------------------------------------------------------ */

/** Canvas 雨线 */
const RainCanvas: React.FC<{ intensity: 'light' | 'heavy' }> = ({ intensity }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    let raf = 0;

    const count = intensity === 'heavy' ? 300 : 120;
    const speed = intensity === 'heavy' ? 14 : 9;
    const len0 = intensity === 'heavy' ? 20 : 14;

    const resize = () => {
      canvas.width = canvas.offsetWidth;
      canvas.height = canvas.offsetHeight;
    };
    resize();
    window.addEventListener('resize', resize);

    const w = () => canvas.width;
    const h = () => canvas.height;
    const drops = Array.from({ length: count }, () => ({
      x: Math.random() * w(),
      y: Math.random() * h(),
      len: len0 + Math.random() * 8,
    }));

    const draw = () => {
      ctx.clearRect(0, 0, w(), h());
      ctx.strokeStyle = 'rgba(180, 200, 230, 0.5)';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      for (const d of drops) {
        ctx.moveTo(d.x, d.y);
        ctx.lineTo(d.x - 2, d.y + d.len);
        d.y += speed;
        d.x -= 0.8;
        if (d.y > h()) {
          d.y = -d.len;
          d.x = Math.random() * w();
        }
      }
      ctx.stroke();
      raf = requestAnimationFrame(draw);
    };
    draw();
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener('resize', resize);
    };
  }, [intensity]);

  return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" />;
};

/** DOM 雪花（CSS @keyframes） */
const SnowLayer: React.FC<{ intensity: 'light' | 'heavy' }> = ({ intensity }) => {
  const count = intensity === 'heavy' ? 60 : 25;
  const flakes = useMemo(
    () =>
      Array.from({ length: count }, (_, i) => ({
        id: i,
        left: Math.random() * 100,
        size: 3 + Math.random() * 6,
        delay: Math.random() * 8,
        duration: 6 + Math.random() * 8,
        drift: (Math.random() - 0.5) * 40,
      })),
    [count],
  );
  return (
    <>
      {/* @keyframes mirage-snowfall 统一维护在 src/index.css */}
      {flakes.map(f => (
        <div
          key={f.id}
          className="absolute rounded-full bg-white/80 pointer-events-none"
          style={{
            left: `${f.left}%`,
            width: f.size,
            height: f.size,
            animation: `mirage-snowfall ${f.duration}s linear ${f.delay}s infinite`,
            '--drift': `${f.drift}px`,
          } as React.CSSProperties}
        />
      ))}
    </>
  );
};

/** 雾层（gradient + motion 平移） */
const FogLayer: React.FC = () => (
  <motion.div
    className="absolute inset-0 pointer-events-none"
    style={{
      background:
        'radial-gradient(ellipse at 30% 50%, rgba(200,200,200,0.35) 0%, transparent 60%), radial-gradient(ellipse at 70% 60%, rgba(220,220,220,0.3) 0%, transparent 55%)',
    }}
    animate={{ x: [0, 30, -20, 0] }}
    transition={{ duration: 20, repeat: Infinity, ease: 'easeInOut' }}
  />
);

/** 闪电（雷暴专用，全屏白闪） */
const LightningFlash: React.FC = () => (
  <motion.div
    className="absolute inset-0 bg-white pointer-events-none"
    animate={{ opacity: [0, 0, 0.7, 0, 0.3, 0] }}
    transition={{
      duration: 0.5,
      repeat: Infinity,
      repeatDelay: 3 + Math.random() * 5,
      times: [0, 0.4, 0.45, 0.5, 0.55, 1],
    }}
  />
);

/* ------------------------------------------------------------------ *
 * 色块滤镜（室外/室内两套，按天气浓度）
 * ------------------------------------------------------------------ */

const OUTDOOR_OVERLAY: Record<WeatherType, string> = {
  '晴': 'transparent',
  '阴': 'rgba(70, 75, 95, 0.18)',
  '小雨': 'rgba(50, 65, 85, 0.28)',
  '大雨': 'rgba(25, 35, 55, 0.42)',
  '雾': 'rgba(175, 180, 190, 0.28)',
  '雷暴': 'rgba(15, 20, 35, 0.52)',
  '小雪': 'rgba(210, 225, 240, 0.18)',
  '大雪': 'rgba(210, 225, 240, 0.28)',
};

const INDOOR_OVERLAY: Record<WeatherType, string> = {
  '晴': 'transparent',
  '阴': 'rgba(70, 75, 95, 0.12)',
  '小雨': 'rgba(50, 65, 85, 0.18)',
  '大雨': 'rgba(25, 35, 55, 0.28)',
  '雾': 'rgba(175, 180, 190, 0.20)',
  '雷暴': 'rgba(15, 20, 35, 0.34)',
  '小雪': 'rgba(210, 225, 240, 0.12)',
  '大雪': 'rgba(210, 225, 240, 0.18)',
};

interface WeatherOverlayProps {
  weather: WeatherType;
  isOutdoor: boolean;
  enabled: boolean;
}

/** 天气叠层主组件 */
export const WeatherOverlay = React.memo(function WeatherOverlay({ weather, isOutdoor, enabled }: WeatherOverlayProps) {
  if (!enabled) return null;
  const overlayColor = (isOutdoor ? OUTDOOR_OVERLAY : INDOOR_OVERLAY)[weather];

  return (
    <div className="absolute inset-0 pointer-events-none overflow-hidden z-[19]">
      {/* 色块滤镜层（带 1s 平滑过渡） */}
      {overlayColor !== 'transparent' && (
        <div
          className="absolute inset-0 transition-all duration-1000"
          style={{ background: overlayColor }}
        />
      )}

      {/* 粒子层：仅室外且开启时 */}
      {isOutdoor && (
        <>
          {(weather === '小雨') && <RainCanvas key="rain-light" intensity="light" />}
          {(weather === '大雨' || weather === '雷暴') && <RainCanvas key="rain-heavy" intensity="heavy" />}
          {weather === '雷暴' && <LightningFlash />}
          {weather === '雾' && <FogLayer />}
          {weather === '小雪' && <SnowLayer key="snow-light" intensity="light" />}
          {weather === '大雪' && <SnowLayer key="snow-heavy" intensity="heavy" />}
        </>
      )}
    </div>
  );
});
