/**
 * 打字机文本组件 — 将打字机状态隔离在独立组件内，避免每帧 setDisplayedText 触发父组件重渲染。
 *
 * 内部管理 displayedText / isTyping 状态，通过 onTypingStateChange 回调通知父组件。
 * 父组件只需在 currentLine / textSpeed / isSkipping 变化时重新挂载本组件。
 */

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { sfx } from '../../audio/sfxPlayer';
import { getTextDelay } from '../../audio/textSettings';
import { cn } from '../../utils';

interface TypingTextProps {
  /** 完整文本 */
  text: string;
  /** 打字速度档位 (0=瞬发, 1=慢, 2=普通, 3=快) */
  textSpeed: number;
  /** 是否跳过模式 */
  isSkipping: boolean;
  /** 当前行类型（影响样式 + 音效） */
  lineType: 'dialog' | 'narrator' | 'thought';
  /** 说话者（用于音效，仅非旁白时播放 blip） */
  speaker?: string;
  /** 通知父组件打字状态变化（true=正在打字, false=打字完毕/跳过） */
  onTypingStateChange?: (isTyping: boolean) => void;
  /** 是否处于调查模式（影响文本可选） */
  isInvestigating?: boolean;
  /** 样式变体 */
  variant: 'mobile' | 'desktop';
  /** 跳过打字机的 ref（供父组件点击跳过使用） */
  skipRef?: React.MutableRefObject<boolean>;
}

export const TypingText = React.memo(function TypingText({
  text,
  textSpeed,
  isSkipping,
  lineType,
  speaker,
  onTypingStateChange,
  isInvestigating = false,
  variant = 'desktop',
  skipRef,
}: TypingTextProps) {
  const [displayedText, setDisplayedText] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const localSkipRef = useRef(false);
  const effectiveSkipRef = skipRef ?? localSkipRef;

  const notifyTypingState = useCallback((typing: boolean) => {
    setIsTyping(typing);
    onTypingStateChange?.(typing);
  }, [onTypingStateChange]);

  useEffect(() => {
    let rafId = 0;
    let cancelled = false;
    effectiveSkipRef.current = false;

    if (textSpeed === 0 || isSkipping) {
      setDisplayedText(text);
      notifyTypingState(false);
      return;
    }

    setDisplayedText('');
    notifyTypingState(true);

    let i = 0;
    const delay = getTextDelay(textSpeed);
    let lastTime = performance.now();

    const typeChar = (timestamp: number) => {
      if (cancelled || effectiveSkipRef.current) {
        if (!cancelled) {
          setDisplayedText(text);
          notifyTypingState(false);
        }
        return;
      }
      const elapsed = timestamp - lastTime;
      if (elapsed < delay) {
        rafId = requestAnimationFrame(typeChar);
        return;
      }
      lastTime = timestamp;
      if (i < text.length) {
        const batchSize = textSpeed >= 3 ? 3 : 1;
        const endIndex = Math.min(i + batchSize, text.length);
        setDisplayedText(text.substring(0, endIndex));
        if (lineType !== 'narrator') sfx.playBlip(speaker);
        i = endIndex;
        rafId = requestAnimationFrame(typeChar);
      } else {
        notifyTypingState(false);
      }
    };

    rafId = requestAnimationFrame(typeChar);

    return () => {
      cancelled = true;
      if (rafId) cancelAnimationFrame(rafId);
    };
  }, [text, textSpeed, isSkipping, lineType, speaker, effectiveSkipRef, notifyTypingState]);

  const isThought = lineType === 'thought';
  const isNarrator = lineType === 'narrator';

  const textClass = variant === 'mobile'
    ? `text-lg font-serif tracking-wide leading-relaxed ${isThought ? 'text-gold-300 italic' : isNarrator ? 'text-paper-200/90' : 'text-paper-100'}`
    : `text-xl md:text-[25px] font-serif tracking-[0.08em] leading-loose ${isThought ? 'text-gold-300 italic' : isNarrator ? 'text-paper-200/90' : 'text-paper-100'}`;

  const cursorClass = variant === 'mobile'
    ? `inline-block w-2 h-4 animate-pulse ml-1 align-middle ${isThought ? 'bg-gold-300' : 'bg-gold-400/90'}`
    : `inline-block w-2.5 h-6 animate-pulse ml-1.5 align-middle rotate-45 ${isThought ? 'bg-gold-300' : 'bg-gold-400/90'}`;

  const style: React.CSSProperties = isInvestigating
    ? { WebkitTouchCallout: 'default', WebkitUserSelect: 'text', userSelect: 'text' }
    : variant === 'desktop'
      ? { willChange: 'contents', textShadow: '0 2px 6px rgba(0,0,0,0.8)' }
      : {};

  return (
    <div
      className={cn(
        'flex-1 overflow-y-auto hide-scrollbar min-h-0 z-10',
        textClass,
        isInvestigating ? 'select-text cursor-text' : 'select-none',
      )}
      style={style}
    >
      {displayedText}
      {isTyping && <span className={cursorClass} />}
    </div>
  );
}, (prev, next) => {
  // 只有当这些 props 真正变化时才重渲染
  return (
    prev.text === next.text &&
    prev.textSpeed === next.textSpeed &&
    prev.isSkipping === next.isSkipping &&
    prev.lineType === next.lineType &&
    prev.speaker === next.speaker &&
    prev.isInvestigating === next.isInvestigating &&
    prev.variant === next.variant
  );
});
