import type { CharacterProfile, GalleryCG, Character } from '../types';
import { CHARACTER_IMAGES, NPC_IMAGES } from './characterImages';

/** 角色图组（生成自 tools/parse_sprite_manifest.mjs 的图床映射；缺失时渲染自动降级） */
function characterImages(name: string) {
  const set = CHARACTER_IMAGES[name];
  return {
    sprites: set?.sprites ?? {},
    illustrationUrl: set?.illustrationUrl,
    avatarUrl: set?.avatarUrl,
  };
}

/** 图鉴三分区（SFW 神态 / NSFW 姿态 / Q版小人） */
function spriteTabs(name: string) {
  const set = CHARACTER_IMAGES[name];
  return { sfw: set?.sfw ?? [], nsfw: set?.nsfw ?? [], chibi: set?.chibi ?? [] };
}

/** NPC 单张立绘：任意情绪都回落到 mo-ren 一张图 */
function npcSprite(file: string): Record<string, string> {
  const url = NPC_IMAGES[file];
  return url ? { 'mo-ren': url } : {};
}

