/**
 * 属性池通用核心 — 登记表结构 / 聊天变量读写 / 洗牌袋抽取
 *
 * 被 evilPoolEngine（邪异）与 normalPoolEngine（路人）共用：
 * 候选集由各池自带的筛选闭包给出（属性放宽规则、性别硬约束都封在闭包里），
 * 核心只负责幂等绑定、桶洗牌袋去重、登记表落档形状。
 */
import type { EvilAsset } from './evilPool';

export type { EvilAsset };

/** 属性池资产的通用形状（EvilAsset / NormalAsset 均满足） */
export interface AttrAssetLike {
  id: string;
  cls: string;
  gender: string;
  age: string;
  variant: string;
  url: string;
}

/** 实例绑定（持久化） */
export interface AttrBinding {
  /** 故事中的实例名（LLM 起的名字，如"水鬼""王屠户"） */
  instanceName: string;
  /** 图 id（池内原始路径） */
  assetId: string;
  /** 图片直链 */
  url: string;
  /** 绑定时命中的属性快照（排查文图一致性用） */
  cls: string;
  gender: string;
  age: string;
  variant: string;
  boundAt: string;
}

/** 登记表（持久化到聊天变量） */
export interface AttrRegistry {
  bindings: Record<string, AttrBinding>;
  usedByBucket: Record<string, string[]>;
}

export function emptyAttrRegistry(): AttrRegistry {
  return { bindings: {}, usedByBucket: {} };
}

/** 从聊天变量读回登记表 */
export function loadAttrRegistry(chatVars: unknown, key: string): AttrRegistry {
  const vars = chatVars as Record<string, unknown> | null;
  const raw = vars?.[key] as AttrRegistry | undefined;
  if (raw && typeof raw === 'object' && raw.bindings && raw.usedByBucket) {
    return { bindings: raw.bindings, usedByBucket: raw.usedByBucket };
  }
  return emptyAttrRegistry();
}

/** 候选筛选闭包：返回空数组表示池中无合规图（核心不配图） */
export type AttrCandidatePicker = (pool: AttrAssetLike[]) => AttrAssetLike[] | undefined;

/** 桶键闭包：同桶内不重复 */
export type AttrBucketOf = (asset: AttrAssetLike) => string;

/**
 * 确保实例已绑定图（幂等）。新实例 → 用 picker 抽候选 → 桶内洗牌袋取未用图；
 * 候选集整袋用尽 → 解禁涉及的桶重抽。
 */
export function drawAttrBindingOp(
  pool: AttrAssetLike[],
  registry: AttrRegistry,
  instanceName: string,
  boundAt: string,
  pickCandidates: AttrCandidatePicker,
  bucketOf: AttrBucketOf,
): { registry: AttrRegistry; binding: AttrBinding | undefined; created: boolean } {
  if (!instanceName) return { registry, binding: undefined, created: false };
  const existing = registry.bindings[instanceName];
  if (existing) return { registry, binding: existing, created: false };

  const candidates = pickCandidates(pool);
  if (!candidates || candidates.length === 0) return { registry, binding: undefined, created: false };

  const usedByBucket = { ...registry.usedByBucket };
  const unused = candidates.filter(a => {
    const bucket = bucketOf(a);
    return !(usedByBucket[bucket] ?? []).includes(a.id);
  });
  let asset: AttrAssetLike | undefined;
  if (unused.length > 0) {
    asset = unused[Math.floor(Math.random() * unused.length)];
  } else {
    // 候选集整袋用尽 → 解禁涉及的桶后重抽
    for (const bucket of new Set(candidates.map(bucketOf))) {
      delete usedByBucket[bucket];
    }
    asset = candidates[Math.floor(Math.random() * candidates.length)];
  }
  if (!asset) return { registry, binding: undefined, created: false };

  const bucket = bucketOf(asset);
  usedByBucket[bucket] = [...(usedByBucket[bucket] ?? []), asset.id];

  const binding: AttrBinding = {
    instanceName,
    assetId: asset.id,
    url: asset.url,
    cls: asset.cls,
    gender: asset.gender,
    age: asset.age,
    variant: asset.variant,
    boundAt,
  };
  return {
    registry: { bindings: { ...registry.bindings, [instanceName]: binding }, usedByBucket },
    binding,
    created: true,
  };
}
