/**
 * 不言生故事 ↔ 聊天世界书同步模块
 *
 * 每个案件在聊天世界书中有一个独立条目「不言生_{caseId}」：
 * - 进行中：蓝灯（constant），at_depth:0 system，order 210（在黄历/天象/暗流/茶楼之前）
 *   不言生针对此案讲过的每一个志怪故事（原话复述）都累积写入此条目，AI 每轮可见——不丢记忆。
 * - 结案后：绿灯（selective），带关键词（案件名 + 玩家关键词），after_character_definition
 *   后续聊到相关话题时激活，AI 能回忆起当年讲过的故事。
 *
 * 条目名用 caseId（不含案件名），改名时条目名不变、只需重写 content。
 *
 * 内容来自 AI 回复末尾的 <storytale title="..."> 原话复述 </storytale> 标记块，
 * 由 storyteller.ts 的 extractStorytales 提取。
 * 故事累积存聊天变量 mirageStorytales（{caseId → [{title, content}]}），前端读改写。
 */

import type { StorytaleExtract } from '../data/storyteller';

/** 聊天世界书条目名称前缀 */
const STORYTALE_ENTRY_PREFIX = '不言生_';

/** 聊天变量中存储所有案件故事的键 */
const STORYTALES_STORAGE_KEY = 'mirageStorytales';

/** 蓝灯条目配置（进行中） */
const ACTIVE_ENTRY_TEMPLATE = {
  enabled: true,
  strategy: {
    type: 'constant' as const,
    keys: [] as (string | RegExp)[],
    keys_secondary: { logic: 'and_any' as const, keys: [] as (string | RegExp)[] },
    scan_depth: 'same_as_global' as const,
  },
  position: {
    type: 'at_depth' as const,
    role: 'system' as const,
    depth: 0,
    order: 210,
  },
  probability: 100,
  recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
};

/** 绿灯条目配置（已结案） */
const CLOSED_ENTRY_TEMPLATE = {
  enabled: true,
  strategy: {
    type: 'selective' as const,
    keys: [] as (string | RegExp)[],
    keys_secondary: { logic: 'and_any' as const, keys: [] as (string | RegExp)[] },
    scan_depth: 'same_as_global' as const,
  },
  position: {
    type: 'after_character_definition' as const,
    role: 'system' as const,
    depth: 0,
    order: 200,
  },
  probability: 100,
  recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
};

/** 根据案件 ID 构造世界书条目名称 */
export function storytaleEntryName(caseId: string): string {
  return `${STORYTALE_ENTRY_PREFIX}${caseId}`;
}

/** 获取或创建聊天世界书，返回世界书名称 */
async function ensureChatWorldbook(): Promise<string | null> {
  try {
    return await getOrCreateChatWorldbook('current');
  } catch (e) {
    console.warn('[幻璃镜] 无法获取聊天世界书', e);
    return null;
  }
}

/** 从聊天变量读取所有案件的故事记录 */
function loadAllStorytales(): Record<string, StorytaleExtract[]> {
  try {
    const vars = getVariables({ type: 'chat' }) as any;
    const data = vars?.[STORYTALES_STORAGE_KEY];
    if (data && typeof data === 'object') return data;
  } catch {
    // 无酒馆环境
  }
  return {};
}

/** 持久化所有案件的故事记录到聊天变量 */
function saveAllStorytales(all: Record<string, StorytaleExtract[]>): void {
  try {
    updateVariablesWith(vars => ({ ...vars, [STORYTALES_STORAGE_KEY]: all }), { type: 'chat' });
  } catch {
    console.warn('[幻璃镜] 无法持久化不言生故事记录');
  }
}

/** 读取某案件的故事列表 */
export function loadStorytalesForCase(caseId: string): StorytaleExtract[] {
  return loadAllStorytales()[caseId] ?? [];
}

/**
 * 将故事列表渲染为世界书条目的 content 文本。
 * 结构：标题行 → 逐夜故事（原话复述）。
 */
function renderStorytaleContent(caseName: string, tales: StorytaleExtract[], isClosed: boolean): string {
  const lines: string[] = [];
  lines.push(`【不言生志怪·${caseName}】`);
  lines.push('状态：' + (isClosed ? '已结案归档' : '案中记述'));
  lines.push('');

  if (tales.length === 0) {
    lines.push('（尚未有故事记述）');
  } else {
    tales.forEach((tale, i) => {
      const titleLabel = tale.title ? `「${tale.title}」` : `（第${i + 1}夜）`;
      lines.push(`◆ 第${i + 1}夜 ${titleLabel}`);
      lines.push(tale.content);
      lines.push('');
    });
  }

  return lines.join('\n');
}

/**
 * 为新案件创建一个空的不言生故事条目（蓝灯）。
 * 在自动创建"初录案卷"或玩家手动创建案件时调用。
 * upsert：已有同名条目则重写，否则追加（与天气/黄历同模式）。
 */
export async function createStorytaleEntry(caseId: string, caseName: string): Promise<boolean> {
  const wbName = await ensureChatWorldbook();
  if (!wbName) return false;

  const content = renderStorytaleContent(caseName, [], false);
  const entryName = storytaleEntryName(caseId);
  try {
    await updateWorldbookWith(wbName, wb => {
      const idx = wb.findIndex(e => e.name === entryName);
      if (idx >= 0) {
        const next = [...wb];
        next[idx] = { ...next[idx], content, ...ACTIVE_ENTRY_TEMPLATE };
        return next;
      }
      return [...wb, { name: entryName, content, ...ACTIVE_ENTRY_TEMPLATE }];
    });
    console.info(`[幻璃镜] 不言生故事条目已创建: ${entryName}`);
    return true;
  } catch (e) {
    console.warn(`[幻璃镜] 创建不言生故事条目失败`, e);
    return false;
  }
}

/**
 * 向某案件追加故事（由 GameContext 在 GENERATION_ENDED 提取到 <storytale> 后调用）。
 * 同时更新聊天变量和世界书条目。
 */
export async function appendStorytalesToCase(
  caseId: string,
  caseName: string,
  newTales: StorytaleExtract[],
  isClosed: boolean = false,
): Promise<boolean> {
  if (newTales.length === 0) return false;

  const all = loadAllStorytales();
  const existing = all[caseId] ?? [];
  // 去重：相同 content 不重复追加
  const filtered = newTales.filter(nt => !existing.some(et => et.content === nt.content));
  if (filtered.length === 0) return false;
  all[caseId] = [...existing, ...filtered];
  saveAllStorytales(all);

  const wbName = await ensureChatWorldbook();
  if (!wbName) return false;

  const content = renderStorytaleContent(caseName, all[caseId], isClosed);
  const entryName = storytaleEntryName(caseId);
  try {
    await updateWorldbookWith(wbName, wb => {
      return wb.map(entry => {
        if (entry.name === entryName) {
          return { ...entry, content };
        }
        return entry;
      });
    });
    console.info(`[幻璃镜] 不言生故事条目已追加 ${filtered.length} 则: ${entryName}`);
    return true;
  } catch (e) {
    console.warn(`[幻璃镜] 追加不言生故事条目失败`, e);
    return false;
  }
}

/**
 * 更新案件名（玩家改名时同步重写条目 content）。
 * 条目名不含案件名，所以只需重写 content。
 */
export async function updateStorytaleEntryName(
  caseId: string,
  newCaseName: string,
  isClosed: boolean,
): Promise<void> {
  const tales = loadStorytalesForCase(caseId);
  const wbName = await ensureChatWorldbook();
  if (!wbName) return;

  const content = renderStorytaleContent(newCaseName, tales, isClosed);
  const entryName = storytaleEntryName(caseId);
  try {
    await updateWorldbookWith(wbName, wb => {
      return wb.map(entry => {
        if (entry.name === entryName) {
          return { ...entry, content };
        }
        return entry;
      });
    });
    console.info(`[幻璃镜] 不言生故事条目已更新案件名: ${entryName}`);
  } catch (e) {
    console.warn(`[幻璃镜] 更新不言生故事条目案件名失败`, e);
  }
}

/**
 * 结案：将蓝灯条目改为绿灯，设置关键词（案件名 + 玩家关键词）。
 */
export async function closeStorytaleEntry(
  caseId: string,
  caseName: string,
  keywords: string[],
): Promise<boolean> {
  const tales = loadStorytalesForCase(caseId);
  const wbName = await ensureChatWorldbook();
  if (!wbName) return false;

  const content = renderStorytaleContent(caseName, tales, true);
  const entryName = storytaleEntryName(caseId);
  // 绿灯关键词 = 案件名 + 玩家关键词（去重）
  const allKeys = [...new Set([caseName, ...keywords])].filter(Boolean);

  try {
    await updateWorldbookWith(wbName, wb => {
      return wb.map(entry => {
        if (entry.name === entryName) {
          return {
            ...entry,
            content,
            strategy: {
              ...entry.strategy,
              type: 'selective' as const,
              keys: allKeys,
            },
            position: {
              ...entry.position,
              type: 'after_character_definition' as const,
              role: 'system' as const,
              depth: 0,
              order: 200,
            },
          };
        }
        return entry;
      });
    });
    console.info(`[幻璃镜] 不言生故事条目已结案(绿灯): ${entryName}`);
    return true;
  } catch (e) {
    console.warn(`[幻璃镜] 结案不言生故事条目失败`, e);
    return false;
  }
}

/**
 * 删除某案件的不言生故事条目（删案时联动）。
 */
export async function deleteStorytaleEntry(caseId: string): Promise<void> {
  const wbName = await ensureChatWorldbook();
  if (!wbName) return;

  const entryName = storytaleEntryName(caseId);
  try {
    await deleteWorldbookEntries(wbName, entry => entry.name === entryName);
    // 同时清理聊天变量中的记录
    const all = loadAllStorytales();
    if (all[caseId]) {
      delete all[caseId];
      saveAllStorytales(all);
    }
    console.info(`[幻璃镜] 不言生故事条目已删除: ${entryName}`);
  } catch (e) {
    console.warn(`[幻璃镜] 删除不言生故事条目失败`, e);
  }
}
