export interface UseTutorialReturn {
  /** 当前应显示的步骤；null = 无需显示 */
  activeStep: TutorialStep | null;
  /** 关闭当前步骤（标记为已完成） */
  dismiss: () => void;
}

export function useTutorial(): UseTutorialReturn {
  const clues = useGameContext(c => c.clues);
  const cases = useGameContext(c => c.cases);
  const currentScreen = useGameContext(c => c.currentScreen);
  const [completedMask, setCompletedMask] = useState<number>(0);
  const [activeStep, setActiveStep] = useState<TutorialStep | null>(null);
  const loadedRef = useRef(false);

  // 初始加载 + 聊天切换时重载
  useEffect(() => {
    const state = loadTutorialState();
    setCompletedMask(state.completedMask);
    loadedRef.current = true;
  }, []);

  // 重算当前应显示的步骤
  useEffect(() => {
    if (!loadedRef.current) return;
    if (currentScreen !== 'game') {
      setActiveStep(null);
      return;
    }

    const allClues = clues.filter(c => c.type === 'clue');
    const unverifiedSoft = allClues.filter(c =>
      (c.category === '证言' || c.category === '传闻') && c.verified !== true
    );
    const hasInference = clues.some(c => c.type === 'inference');
    const hasDeduction = clues.some(c => c.type === 'deduction');
    const activeCases = cases.filter(c => c.status === 'active');

    // 推论三轴线是否各有一条已验证推论
    const verifiedDeductions = clues.filter(c => c.type === 'deduction' && c.status === 'true');
    const hasHow = verifiedDeductions.some(d => d.deductionType === 'how');
    const hasWhy = verifiedDeductions.some(d => d.deductionType === 'why');
    const hasWho = verifiedDeductions.some(d => d.deductionType === 'who');
    const allAxesReady = hasHow && hasWhy && hasWho;

    // 按顺序检查：找到第一个未完成且满足触发条件的步骤
    let nextStep: TutorialStep | null = null;

    if (!isStepCompleted(completedMask, 0) && allClues.length === 0) {
      nextStep = 0;
    } else if (!isStepCompleted(completedMask, 1) && allClues.length > 0) {
      nextStep = 1;
    } else if (!isStepCompleted(completedMask, 2) && unverifiedSoft.length > 0) {
      nextStep = 2;
    } else if (!isStepCompleted(completedMask, 3) && allClues.length >= 2) {
      nextStep = 3;
    } else if (!isStepCompleted(completedMask, 4) && hasInference) {
      nextStep = 4;
    } else if (!isStepCompleted(completedMask, 5) && hasDeduction) {
      nextStep = 5;
    } else if (!isStepCompleted(completedMask, 6) && allAxesReady && activeCases.length > 0) {
      nextStep = 6;
    }

    setActiveStep(nextStep);
  }, [completedMask, clues, cases, currentScreen]);

  const dismiss = useCallback(() => {
    if (activeStep == null) return;
    const newMask = markStepCompleted(completedMask, activeStep);
    setCompletedMask(newMask);
    persistTutorialState(newMask);
    setActiveStep(null);
  }, [activeStep, completedMask]);

  return { activeStep, dismiss };
}
