/**
 * 随机宅邸池引擎 — 类别判定 / 洗牌袋 / 实例登记 / 场景取图
 *
 * 机制见 docs/随机宅邸池设计方案.md：
 * - LLM 即兴命名一次性宅邸地点（如"豫王府"），前端只识别类别，从对应档位
 *   的洗牌袋抽一套未用图套绑定；绑定落聊天变量存档，重访同图。
 * - 已用标记按档位独立累计，整袋用尽才全部解禁重洗。
 * - 名字与图解耦：图套原始名字（岷王府等）只是资产名，不进叙事。
 */
import { LOCATION_POOL, POOL_TIERS, type PoolAsset, type PoolScene } from './locationPool';

// 供地图等消费方统一从引擎引入
export { POOL_TIERS };

/** 实例绑定（持久化） */
export interface PoolBinding {
  /** 故事中的实例名（LLM 即兴起的名字） */
  instanceName: string;
  /** 图套 id，格式 `${tier}/${assetName}` */
  assetId: string;
  tier: string;
  /** 绑定时的在办案件；结案后地图摘印 */
  caseId?: string;
  boundAt: string;
}

/** 登记表（持久化到聊天变量） */
export interface PoolRegistry {
  /** 实例名 → 绑定 */
  bindings: Record<string, PoolBinding>;
  /** 档位 → 已用图套 id 列表（整袋用尽时清空重洗） */
  usedByTier: Record<string, string[]>;
}

export const POOL_STORAGE_KEY = 'miragePoolState';

export const EMPTY_POOL_REGISTRY: PoolRegistry = { bindings: {}, usedByTier: {} };

/** 从聊天变量读回登记表 */
export function loadPoolRegistry(chatVars: unknown): PoolRegistry {
  const vars = chatVars as Record<string, unknown> | null;
  const raw = vars?.[POOL_STORAGE_KEY] as PoolRegistry | undefined;
  if (raw && typeof raw === 'object' && raw.bindings && raw.usedByTier) {
    return { bindings: raw.bindings, usedByTier: raw.usedByTier };
  }
  return EMPTY_POOL_REGISTRY;
}

// ── 类别判定 ──

/** 场景名证据：出现亲王专有殿名 → 亲王档 */
const QINWANG_SCENE_HINTS = ['承运殿', '存心殿'];

/**
 * 判定实例名所属档位。
 * @param instanceName 实例名（如"豫亲王府""某勋贵宅邸"）
 * @param sceneName    场景名（如"承运殿"），用于泛称时的档位佐证
 */
export function detectPoolTier(instanceName: string, sceneName?: string): string | undefined {
  if (!instanceName) return undefined;
  if (sceneName && QINWANG_SCENE_HINTS.includes(sceneName)) return 'qinwang';

  const rules: [RegExp, string][] = [
    [/亲王府$/, 'qinwang'],
    [/郡王府$/, 'junwang'],
    // 泛称"某王府"（如"豫王府"——街坊口语不会说"豫亲王府"）默认按亲王档取图
    [/王府$/, 'qinwang'],
    [/公府$/, 'guogong'],
    [/侯府$/, 'hou'],
    [/伯府$/, 'bo'],
    [/(掌印|秉笔|随堂|内官|珰)/, 'dang'],
    [/第$/, 'guandi'],
    [/会馆$/, 'huiguan'],
    [/(商|号|栈)/, 'shang'],
    [/铺/, 'pu'],
    [/(村|庄|寨|户|农家|田)/, 'cunzhai'],
    [/(民宅|民院|杂院|宅|院)$/, 'min'],
    [/府$/, 'gaoguan'],
    [/妃|嫔|娘娘|宫$/, 'xianshi'],
  ];
  for (const [re, tier] of rules) {
    if (re.test(instanceName)) return tier;
  }
  return undefined;
}

/** 解析池子路径：`[scene:实例名/场景名]` 或实例名嵌在完整路径中段 */
export function parsePoolPath(path: string): { instanceName: string; sceneName?: string } | undefined {
  const segments = path.split('/').map(s => s.trim()).filter(Boolean);
  if (segments.length === 0) return undefined;
  const sceneName = segments.length > 1 ? segments[segments.length - 1] : undefined;
  // 候选实例名：除末段外的段（单段时取末段本身）
  const candidates = segments.length > 1 ? segments.slice(0, -1) : segments;
  for (const seg of candidates) {
    if (detectPoolTier(seg, sceneName)) return { instanceName: seg, sceneName };
  }
  return undefined;
}

// ── 洗牌袋 ──

function assetsOfTier(tier: string): PoolAsset[] {
  return LOCATION_POOL.filter(a => a.tier === tier);
}

export function getPoolAsset(assetId: string): PoolAsset | undefined {
  const idx = LOCATION_POOL.findIndex(a => `${a.tier}/${a.name}` === assetId);
  return idx >= 0 ? LOCATION_POOL[idx] : undefined;
}

/**
 * 从指定档位抽一个未用图套。袋子用尽时整袋解禁重洗（reset=true）。
 * @returns 新登记表 + 抽中的图套 id
 */
export function drawPoolAsset(
  registry: PoolRegistry,
  tier: string,
): { registry: PoolRegistry; assetId: string; reset: boolean } {
  const inBag = POOL_TIERS[tier]?.inBag !== false;
  const used = registry.usedByTier[tier] ?? [];
  let pool = assetsOfTier(tier);
  if (pool.length === 0) return { registry, assetId: '', reset: false };

  let reset = false;
  let unused = pool.filter(a => !used.includes(`${a.tier}/${a.name}`));
  if (unused.length === 0) {
    if (!inBag) {
      // 不进袋的档位（限时池）：自由复用，不标记
      unused = pool;
    } else {
      reset = true;
      unused = pool;
    }
  }
  const asset = unused[Math.floor(Math.random() * unused.length)];
  const assetId = `${asset.tier}/${asset.name}`;
  const nextUsed = inBag && !used.includes(assetId) ? [...used, assetId] : used;
  return {
    registry: { ...registry, usedByTier: { ...registry.usedByTier, [tier]: nextUsed } },
    assetId,
    reset,
  };
}

/** 确保实例已绑定图套；幂等。tier 无法判定时返回原登记表 + undefined 绑定 */
export function ensurePoolBinding(
  registry: PoolRegistry,
  instanceName: string,
  opts: { sceneName?: string; caseId?: string; boundAt?: string } = {},
): { registry: PoolRegistry; binding?: PoolBinding; created: boolean; poolReset: boolean } {
  const existing = registry.bindings[instanceName];
  if (existing) return { registry, binding: existing, created: false, poolReset: false };

  const tier = detectPoolTier(instanceName, opts.sceneName);
  if (!tier) return { registry, binding: undefined, created: false, poolReset: false };

  const { registry: reg2, assetId, reset } = drawPoolAsset(registry, tier);
  if (!assetId) return { registry, binding: undefined, created: false, poolReset: false };

  const binding: PoolBinding = {
    instanceName,
    assetId,
    tier,
    caseId: opts.caseId,
    boundAt: opts.boundAt ?? '',
  };
  return {
    registry: { ...reg2, bindings: { ...reg2.bindings, [instanceName]: binding } },
    binding,
    created: true,
    poolReset: reset,
  };
}

// ── 场景取图 ──

/** 同功能场景别名组：实例场景名 → 图套实际场景名 */
const SCENE_ALIAS: string[][] = [
  ['承运殿', '存心殿', '正殿', '正堂', '正房', '堂屋', '大堂'],
  ['寝阁', '卧房', '厢房', '客房', '陋室', '棚屋', '石屋', '寝院', '家庙'],
  ['书房', '账房', '花厅', '密室', '仓房'],
  ['大门前庭', '门庭', '柴门', '院场'],
  ['后园', '后院', '院落', '庭院', '演武园', '场院', '院子', '农家院', '街巷'],
];

function resolveSceneKey(asset: PoolAsset, sceneName?: string): { key: string; scene: PoolScene } | undefined {
  const keys = Object.keys(asset.scenes);
  if (keys.length === 0) return undefined;
  if (sceneName && asset.scenes[sceneName]) return { key: sceneName, scene: asset.scenes[sceneName] };
  if (sceneName) {
    const group = SCENE_ALIAS.find(g => g.includes(sceneName));
    if (group) {
      const hit = group.find(k => asset.scenes[k]);
      if (hit) return { key: hit, scene: asset.scenes[hit] };
    }
  }
  return { key: keys[0], scene: asset.scenes[keys[0]] };
}

/** 按天气昼夜从图套取图（口径与 getLocationImageSmart 一致） */
export function resolvePoolSceneImage(
  asset: PoolAsset,
  sceneName: string | undefined,
  weather: 'sunny' | 'cloudy' | 'snowy',
  time: 'day' | 'night',
): string | undefined {
  const resolved = resolveSceneKey(asset, sceneName);
  if (!resolved) return undefined;
  const { scene } = resolved;
  if (scene.type === 'indoor') {
    return scene.variants[time === 'night' ? '夜' : '昼'];
  }
  const weatherChar = weather === 'sunny' ? '晴' : weather === 'cloudy' ? '阴' : '雪';
  const precise = scene.variants[`${weatherChar}${time === 'night' ? '夜' : '昼'}`];
  return precise || scene.variants[time === 'night' ? '夜' : '昼'];
}

// ── 地图查询辅助 ──

export interface PoolPinInfo {
  binding: PoolBinding;
  asset: PoolAsset;
  tierLabel: string;
  /** 绑定案件是否已结案（结案 → 摘印） */
  closed: boolean;
}

/** 某大区下的池子实例 pin（含已摘印的灰显项） */
export function getPoolPinsForRegion(
  registry: PoolRegistry,
  regionName: string,
  cases: { id: string; status: string }[],
): PoolPinInfo[] {
  const closedIds = new Set(cases.filter(c => c.status === 'closed').map(c => c.id));
  const pins: PoolPinInfo[] = [];
  for (const binding of Object.values(registry.bindings)) {
    const meta = POOL_TIERS[binding.tier];
    if (!meta || meta.region !== regionName) continue;
    const asset = getPoolAsset(binding.assetId);
    if (!asset) continue;
    pins.push({
      binding,
      asset,
      tierLabel: meta.label,
      closed: binding.caseId ? closedIds.has(binding.caseId) : false,
    });
  }
  return pins;
}
