/**
 * MVU (MagVarUpdate) 前端适配层 — 幻璃镜
 *
 * 职责：stat_data 的读写、就绪探测、种子写入、事件订阅。阶梯判定与条目渲染不在此层。
 *
 * 权威与出处（sillytavern-api-reference 核实记录）：
 * - symbol: Mvu.getMvuData / replaceMvuData / events.VARIABLE_UPDATE_ENDED
 *   surface: Tavern Helper iframe 全局（MVU 框架脚本注入）
 *   provenance: @types/iframe/exported.mvu.d.ts（本仓库声明快照）；运行时用法同仓库 src/租借男友/src/state/GameContext.tsx
 *   confidence: high（声明 + 同仓运行时先例）
 *   runtime_check: 真机待验（框架脚本须已在宿主安装：酒馆助手脚本 import MagVarUpdate CDN bundle）
 * - 更新语法为 <UpdateVariable><JSONPatch>（replace/delta/insert/remove/move），由 MVU 框架解析；
 *   前端不解析更新块，只读结果与做夹逼。
 *
 * 降级策略：MVU 未就绪时读回退占位时间，全部静默不抛错——前端功能不因框架缺席而崩溃。
 */

import type { GameTime } from '../store/GameContext';
import { eraYearToSolarYear, solarYearToEraYear } from '../data/almanacNote';

/** MVU 缺席/新聊天时的占位时间（原 GameContext.getGameTimePlaceholder 的值） */
export const DEFAULT_GAME_TIME: GameTime = { eraYear: 23, month: 8, day: 15, hour: 19, minute: 0 };

/** MVU 框架就绪探测：waitGlobalInitialized('Mvu') 带超时，超时后回退 window.Mvu 探测 */
export async function ensureMvuReady(timeoutMs = 8000): Promise<boolean> {
  try {
    await Promise.race([
      (globalThis as any).waitGlobalInitialized?.('Mvu'),
      new Promise((_, rej) => setTimeout(() => rej(new Error('mvu wait timeout')), timeoutMs)),
    ]);
    return !!(globalThis as any).Mvu;
  } catch {
    try {
      return typeof window !== 'undefined' && !!(window as any).Mvu;
    } catch {
      return false;
    }
  }
}

/** 读取当前 stat_data：优先指定楼层（默认最新）的 MVU 存储，回退聊天变量 */
export function readStatData(messageId?: number): Record<string, any> | null {
  try {
    const mvu = (globalThis as any).Mvu;
    if (mvu) {
      const data = mvu.getMvuData({ type: 'message', message_id: messageId ?? 'latest' });
      const sd = data?.stat_data;
      if (sd && typeof sd === 'object') return sd;
    }
  } catch {
    // 楼层读取失败（如空聊天）时走聊天变量回退
  }
  // 仅当未指定楼层（读最新）时才回退到聊天变量
  if (messageId == null) {
    try {
      const chat = getVariables({ type: 'chat' }) as any;
      const sd = chat?.stat_data;
      if (sd && typeof sd === 'object') return sd;
    } catch {
      // 无酒馆环境（浏览器裸跑预览）
    }
  }
  return null;
}

function clampNum(v: any, lo: number, hi: number, dflt: number): number {
  const n = Math.round(Number(v));
  return Number.isFinite(n) ? Math.min(hi, Math.max(lo, n)) : dflt;
}

/** 从任意"时间"对象安全读出 GameTime（字段缺失/非法逐项回退默认值） */
function gameTimeFrom(t: any): GameTime {
  return {
    eraYear: clampNum(t?.年, 1, 9999, DEFAULT_GAME_TIME.eraYear),
    month: clampNum(t?.月, 1, 12, DEFAULT_GAME_TIME.month),
    day: clampNum(t?.日, 1, 31, DEFAULT_GAME_TIME.day),
    hour: clampNum(t?.小时, 0, 23, DEFAULT_GAME_TIME.hour),
    minute: clampNum(t?.分钟, 0, 59, DEFAULT_GAME_TIME.minute),
  };
}

/** 小时推进（真公历进位：大小月/跨月/跨年由 Date 引擎处理），供前端直接拨快时钟使用 */
function addHours(gt: GameTime, hours: number): GameTime {
  const d = new Date(eraYearToSolarYear(gt.eraYear), gt.month - 1, gt.day, gt.hour, gt.minute);
  d.setHours(d.getHours() + hours);
  return {
    eraYear: solarYearToEraYear(d.getFullYear()),
    month: d.getMonth() + 1,
    day: d.getDate(),
    hour: d.getHours(),
    minute: d.getMinutes(),
  };
}

/** 读取游戏时间（stat_data.时间），无效字段逐项夹逼，整体缺失回退占位 */
export function readGameTime(messageId?: number): GameTime {
  return gameTimeFrom(readStatData(messageId)?.时间);
}

/** 读取当前地点（stat_data.地点.当前地点） */
export function readLocation(messageId?: number): string {
  const v = readStatData(messageId)?.地点?.当前地点;
  return typeof v === 'string' ? v : '';
}

/** 读取暗流戒心表（stat_data.暗流，目标名 → 0~100；可传变量表源） */
export function readSuspicion(sd?: Record<string, any> | null): Record<string, number> {
  const s = (sd ?? readStatData())?.暗流;
  if (!s || typeof s !== 'object') return {};
  const out: Record<string, number> = {};
  for (const k of Object.keys(s)) {
    const n = Number(s[k]);
    if (Number.isFinite(n)) out[k] = n;
  }
  return out;
}

/** 读取未消解犯忌数（stat_data.因果.犯忌；可传变量表源，事件内用传入值避免读到旧楼层） */
export function readTabooCount(sd?: Record<string, any> | null): number {
  return clampNum((sd ?? readStatData())?.因果?.犯忌, 0, 99, 0);
}

/**
 * 数值收账夹逼（官方范式：在 VARIABLE_UPDATE_ENDED 事件内直接改写 variables，
 * 框架随后落盘——勿在此事件里用 getMvuData 重读，时序上可能拿到旧值）。
 * 暗流戒心约束到 0~100，犯忌数约束到 0~99。
 * @returns 是否有修改
 */
export function clampStatNumbers(variables: any): boolean {
  try {
    const sd = variables?.stat_data;
    if (!sd) return false;
    let changed = false;
    const s = sd.暗流;
    if (s && typeof s === 'object') {
      for (const k of Object.keys(s)) {
        const v = clampNum(s[k], 0, 100, 0);
        if (v !== s[k]) {
          s[k] = v;
          changed = true;
        }
      }
    }
    if (sd.因果 && typeof sd.因果 === 'object' && sd.因果.犯忌 != null) {
      const v = clampNum(sd.因果.犯忌, 0, 99, 0);
      if (v !== sd.因果.犯忌) {
        sd.因果.犯忌 = v;
        changed = true;
      }
    }
    return changed;
  } catch {
    return false;
  }
}

/** stat_data 种子：时间/地点/暗流 三字段缺失时写入初始值（对旧聊天同样生效） */
export async function seedStatDataIfMissing(): Promise<boolean> {
  if (readStatData()?.时间) return false;
  const seed = {
    时间: { 年: DEFAULT_GAME_TIME.eraYear, 月: DEFAULT_GAME_TIME.month, 日: DEFAULT_GAME_TIME.day, 小时: DEFAULT_GAME_TIME.hour, 分钟: DEFAULT_GAME_TIME.minute },
    地点: { 当前地点: '漏刻房' },
    暗流: {},
    因果: { 犯忌: 0 },
  };
  try {
    const mvu = (globalThis as any).Mvu;
    const lastId = getLastMessageId();
    if (mvu && lastId != null) {
      const data = mvu.getMvuData({ type: 'message', message_id: lastId });
      data.stat_data = { ...(data?.stat_data ?? {}), ...seed };
      await mvu.replaceMvuData(data, { type: 'message', message_id: lastId });
      console.info('[幻璃镜] stat_data 种子已写入最新楼层');
      return true;
    }
  } catch (e) {
    console.warn('[幻璃镜] stat_data 楼层种子失败，回退聊天变量', e);
  }
  try {
    updateVariablesWith(vars => ({ ...vars, stat_data: { ...(vars as any).stat_data, ...seed } }), { type: 'chat' });
    console.info('[幻璃镜] stat_data 种子已写入聊天变量');
    return true;
  } catch {
    console.warn('[幻璃镜] 无法写入 stat_data 种子');
    return false;
  }
}

/**
 * 前端直接拨快时钟（收录线索等行动的时辰代价，不经 AI 报告）。
 * 真公历进位；MVU 缺席时回退聊天变量。返回拨快后的时间。
 */
export async function addGameHours(hours: number): Promise<GameTime | null> {
  const base = readGameTime();
  const advanced = addHours(base, hours);
  try {
    const mvu = (globalThis as any).Mvu;
    const lastId = getLastMessageId();
    if (mvu && lastId != null) {
      const data = mvu.getMvuData({ type: 'message', message_id: lastId });
      if (data?.stat_data?.时间) {
        data.stat_data.时间 = {
          年: advanced.eraYear,
          月: advanced.month,
          日: advanced.day,
          小时: advanced.hour,
          分钟: advanced.minute,
        };
        await mvu.replaceMvuData(data, { type: 'message', message_id: lastId });
        return advanced;
      }
    }
  } catch {
    // 楼层写入失败时回退聊天变量
  }
  try {
    updateVariablesWith(vars => {
      const sd = (vars as any).stat_data ?? {};
      return {
        ...vars,
        stat_data: {
          ...sd,
          时间: { 年: advanced.eraYear, 月: advanced.month, 日: advanced.day, 小时: advanced.hour, 分钟: advanced.minute },
        },
      };
    }, { type: 'chat' });
    return advanced;
  } catch {
    return null;
  }
}

/** 清空暗流（结案时调用；MVU 缺席时回退聊天变量） */
export async function clearSuspicion(): Promise<void> {
  try {
    const mvu = (globalThis as any).Mvu;
    const lastId = getLastMessageId();
    if (mvu && lastId != null) {
      const data = mvu.getMvuData({ type: 'message', message_id: lastId });
      if (data?.stat_data) {
        data.stat_data.暗流 = {};
        await mvu.replaceMvuData(data, { type: 'message', message_id: lastId });
        return;
      }
    }
  } catch {
    // 楼层写入失败时回退聊天变量
  }
  try {
    updateVariablesWith(vars => {
      const sd = (vars as any).stat_data;
      if (sd) sd.暗流 = {};
      return { ...vars };
    }, { type: 'chat' });
  } catch {
    // 无酒馆环境
  }
}

/** 订阅 MVU 变量更新结束事件（透传更新后/更新前两份变量表），返回解绑函数 */
export function onVariableUpdateEnded(cb: (variables: any, variablesBefore: any) => void): () => void {
  try {
    const mvu = (globalThis as any).Mvu;
    if (!mvu?.events?.VARIABLE_UPDATE_ENDED) return () => {};
    const ret = eventOn(mvu.events.VARIABLE_UPDATE_ENDED, (variables: any, variablesBefore: any) => {
      cb(variables, variablesBefore);
    });
    return () => {
      try {
        ret?.stop?.();
      } catch {
        // 解绑失败无需处理
      }
    };
  } catch {
    return () => {};
  }
}
