/**
 * 黄历历注 ↔ 聊天世界书同步模块
 *
 * 聊天世界书中固定一条蓝灯条目「黄历_今日」：
 * - constant（蓝灯）：无需关键词，AI 每轮可见——历注是环境状态，犯忌发生在玩家说出行动的那一刻，不能靠关键词触发；
 * - at_depth:0 system，order 200：与案件条目同层（Gemini 对 D0 内容读取最稳），同深度按 order 排序合并为一条 system；
 * - 翻页 = 整条重写 content：旧日历注不残留，prompt 里永远只有今天的宜忌；
 * - 内容由 almanacNote 纯本地计算，不调用任何 AI API。
 *
 * 日期键存聊天变量 mirageAlmanacDate（"eraYear-month-day"）：
 * 当前游戏日期与键不一致（或条目缺失/被手动删除）时才写入，其余情况零开销。
 * 时间推进 / MVU stat_data.时间 接入后，在日期变更处调用 ensureAlmanacEntry 即可自动翻页。
 */

import type { GameTime } from '../store/GameContext';
import { buildAlmanacContent } from '../data/almanacNote';
import { readTabooCount } from './mvu';

/** 聊天世界书条目名称（固定单条，不按日期建多条） */
const ALMANAC_ENTRY_NAME = '黄历_今日';

/** 聊天变量中记录"当前已写入的历注日期"的键 */
const ALMANAC_DATE_KEY = 'mirageAlmanacDate';

/** 蓝灯条目配置（与 clueWorldbook 的 ACTIVE_ENTRY_TEMPLATE 同构，仅深度不同） */
const ALMANAC_ENTRY_TEMPLATE = {
  enabled: true,
  strategy: {
    type: 'constant' as const,
    keys: [] as (string | RegExp)[],
    keys_secondary: { logic: 'and_any' as const, keys: [] as (string | RegExp)[] },
    scan_depth: 'same_as_global' as const,
  },
  position: {
    type: 'at_depth' as const,
    role: 'system' as const,
    depth: 0,
    order: 200,
  },
  probability: 100,
  recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
};

/** 历注内容版本：模板/映射表/条目配置变更时 +1，让旧聊天的条目在下次进入时自动重写归一 */
const ALMANAC_CONTENT_VERSION = 6;

/** 游戏时间 → 日期键（含内容版本；跨日或版本变更才重写，时辰以下不区分） */
function almanacDateKey(gt: GameTime): string {
  return `v${ALMANAC_CONTENT_VERSION}-${gt.eraYear}-${gt.month}-${gt.day}`;
}

/** 获取或创建聊天世界书，返回世界书名称 */
async function ensureChatWorldbook(): Promise<string | null> {
  try {
    return await getOrCreateChatWorldbook('current');
  } catch (e) {
    console.warn('[幻璃镜] 无法获取聊天世界书', e);
    return null;
  }
}

/**
 * 确保「黄历_今日」条目与当前游戏日期/因果账一致（幂等）。
 * 条目缺失、被手动删除或日期/犯忌数变化时创建/重写，其余情况直接跳过。
 * @returns 是否发生了写入
 */
export async function ensureAlmanacEntry(gt: GameTime): Promise<boolean> {
  const taboo = readTabooCount();
  const nextKey = `v${ALMANAC_CONTENT_VERSION}-${almanacDateKey(gt)}-${taboo}`;
  try {
    const vars = getVariables({ type: 'chat' }) as any;
    if (vars?.[ALMANAC_DATE_KEY] === nextKey) return false;
  } catch {
    // 读不到聊天变量时继续走写入路径：宁可重写，不可缺条
  }

  const wbName = await ensureChatWorldbook();
  if (!wbName) return false;

  const content = buildAlmanacContent(gt, taboo);
  try {
    await updateWorldbookWith(wbName, wb => {
      const idx = wb.findIndex(e => e.name === ALMANAC_ENTRY_NAME);
      if (idx >= 0) {
        const next = [...wb];
        // 重写时以模板归一系统托管字段（深度/策略/递归），自愈旧版条目（如 D1→D0 搬层）
        next[idx] = { ...next[idx], content, ...ALMANAC_ENTRY_TEMPLATE };
        return next;
      }
      // 条目不存在（新聊天 / 被手动删除）：追加补回
      return [...wb, { name: ALMANAC_ENTRY_NAME, content, ...ALMANAC_ENTRY_TEMPLATE }];
    });
  } catch (e) {
    console.warn('[幻璃镜] 写入黄历条目失败', e);
    return false;
  }

  try {
    updateVariablesWith(vars => ({ ...vars, [ALMANAC_DATE_KEY]: nextKey }), { type: 'chat' });
  } catch {
    console.warn('[幻璃镜] 无法持久化黄历日期键（下次仍会重写，不影响正确性）');
  }
  console.info('[幻璃镜] 黄历条目已就绪:', nextKey);
  return true;
}
