/**
 * 天象 ↔ 聊天世界书同步模块
 *
 * 聊天世界书中固定一条蓝灯条目「天象_当前」：
 * - constant（蓝灯）：天象是环境状态，AI 每轮可见，不能靠关键词触发；
 * - at_depth:0 system，order 190：与案件/黄历条目同层（Gemini 对 D0 内容读取最稳），order 略低排在其后；
 * - 天气变化时整条重写（历注一日一翻，天象随变随翻——两者粒度不同故独立成条）；
 * - 内容由 weather.ts 纯本地构建，不调用任何 AI API。
 *
 * 键 = 内容版本 + 天气 + 天象日志末条序号：天气没变零开销；
 * 天气回写通道（extractWeatherFromText）负责承接 AI 发起的突变，系统记档后由本模块翻页。
 */

import { buildWeatherContent, loadWeatherLog, type WeatherType, type WeatherLogEntry } from '../data/weather';
import { readGameTime, readLocation } from './mvu';

/** 聊天世界书条目名称（固定单条） */
const WEATHER_ENTRY_NAME = '天象_当前';

/** 聊天变量中记录"当前已写入的天象状态"的键 */
const WEATHER_NOTE_KEY = 'mirageWeatherNoteKey';

/** 历注内容版本：模板/效应表/条目配置变更时 +1，让旧聊天的条目在下次进入时自动重写归一 */
const WEATHER_CONTENT_VERSION = 3;

/** 蓝灯条目配置（与 clueWorldbook 的 ACTIVE_ENTRY_TEMPLATE 同构，仅深度/次序不同） */
const WEATHER_ENTRY_TEMPLATE = {
  enabled: true,
  strategy: {
    type: 'constant' as const,
    keys: [] as (string | RegExp)[],
    keys_secondary: { logic: 'and_any' as const, keys: [] as (string | RegExp)[] },
    scan_depth: 'same_as_global' as const,
  },
  position: {
    type: 'at_depth' as const,
    role: 'system' as const,
    depth: 0,
    order: 190,
  },
  probability: 100,
  recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
};

/** 获取或创建聊天世界书，返回世界书名称 */
async function ensureChatWorldbook(): Promise<string | null> {
  try {
    return await getOrCreateChatWorldbook('current');
  } catch (e) {
    console.warn('[幻璃镜] 无法获取聊天世界书', e);
    return null;
  }
}

/**
 * 确保「天象_当前」条目与当前天气一致（幂等）。
 * 条目缺失、被手动删除或天气/日志变化时创建/重写，其余情况直接跳过。
 * @returns 是否发生了写入
 */
export async function ensureWeatherEntry(weather: WeatherType): Promise<boolean> {
  let log: WeatherLogEntry[] = [];
  try {
    log = loadWeatherLog();
  } catch {
    // 日志读不到时按空记录构建，不影响当前天气写入
  }
  const gt = readGameTime();
  const location = readLocation();
  const lastSeq = log.length > 0 ? log[log.length - 1].seq : 0;
  // 键含时辰与所在：时辰/地点随 AI 时间推进变化时也会翻新此条目
  const nextKey = `wv${WEATHER_CONTENT_VERSION}-${weather}-${lastSeq}-${gt.hour}-${location}`;

  try {
    const vars = getVariables({ type: 'chat' }) as any;
    if (vars?.[WEATHER_NOTE_KEY] === nextKey) return false;
  } catch {
    // 读不到聊天变量时继续走写入路径：宁可重写，不可缺条
  }

  const wbName = await ensureChatWorldbook();
  if (!wbName) return false;

  const content = buildWeatherContent(weather, gt, location, log);
  try {
    await updateWorldbookWith(wbName, wb => {
      const idx = wb.findIndex(e => e.name === WEATHER_ENTRY_NAME);
      if (idx >= 0) {
        const next = [...wb];
        // 重写时以模板归一系统托管字段（深度/策略/递归），自愈旧版条目（如 D1→D0 搬层）
        next[idx] = { ...next[idx], content, ...WEATHER_ENTRY_TEMPLATE };
        return next;
      }
      // 条目不存在（新聊天 / 被手动删除）：追加补回
      return [...wb, { name: WEATHER_ENTRY_NAME, content, ...WEATHER_ENTRY_TEMPLATE }];
    });
  } catch (e) {
    console.warn('[幻璃镜] 写入天象条目失败', e);
    return false;
  }

  try {
    updateVariablesWith(vars => ({ ...vars, [WEATHER_NOTE_KEY]: nextKey }), { type: 'chat' });
  } catch {
    console.warn('[幻璃镜] 无法持久化天象状态键（下次仍会重写，不影响正确性）');
  }
  console.info('[幻璃镜] 天象条目已就绪:', nextKey);
  return true;
}
