/**
 * 路人随机池引擎 — 正常人类 NPC 的属性抽取（第一批图库，915 张）
 *
 * 与邪异池共用 attrPoolCore，差异在候选链：
 * - 标签写了 职业/身份（variant）→ 模糊匹配（互相包含即可，"药铺掌柜"能命中
 *   "药铺掌柜坐堂大夫"）+ 性别 + 年龄；找不到含糊不得——职业声明了就不硬凑，宁可不配图；
 *   仅在同职业内放宽年龄（正文"老屠户"池中只有中年屠户时，仍是屠户）。
 * - 未写 职业/身份 → 只落 A1 路人矩阵（专用的无名路人库）按性别+年龄抽。
 * - 性别为硬约束，任何层级不跨性别；无"无"性别兜底（正常人必须有性别）。
 */
import { NORMAL_POOL, type NormalAsset } from './normalPool';
import { drawAttrBindingOp, emptyAttrRegistry, loadAttrRegistry, type AttrBinding, type AttrRegistry, type AttrAssetLike } from './attrPoolCore';

export { NORMAL_POOL };
export type { NormalAsset };

/** 实例绑定（持久化） */
export type NormalBinding = AttrBinding;

/** 登记表（持久化到聊天变量） */
export type NormalRegistry = AttrRegistry;

export const NORMAL_STORAGE_KEY = 'mirageNormalPoolState';

export const EMPTY_NORMAL_REGISTRY: NormalRegistry = emptyAttrRegistry();

/** 从聊天变量读回登记表 */
export function loadNormalRegistry(chatVars: unknown): NormalRegistry {
  return loadAttrRegistry(chatVars, NORMAL_STORAGE_KEY);
}

// ── 标签解析 ──

/** LLM 声明的路人属性（未给的键交给前端随机；variant 含职业/身份两种叫法） */
export interface NormalAttrs {
  gender?: string;
  age?: string;
  variant?: string;
}

/** [路人:名称,键=值,...] — 键序随意：性别/年龄/职业(身份) */
export const NORMAL_TAG_RE = /^\[路人:([^\]]+?)\]$/;
const NORMAL_SCAN_RE = /\[路人:([^\]\n]+?)\]/g;

/** 解析单个标签内容 → { name, attrs }；格式非法返回 undefined */
export function parseNormalTag(body: string): { name: string; attrs: NormalAttrs } | undefined {
  const parts = body.split(/[，,]/).map(s => s.trim()).filter(Boolean);
  if (parts.length === 0) return undefined;
  const name = parts[0];
  if (!name) return undefined;
  const attrs: NormalAttrs = {};
  for (const part of parts.slice(1)) {
    const eq = part.indexOf('=');
    if (eq <= 0) continue;
    const key = part.slice(0, eq).trim();
    const value = part.slice(eq + 1).trim();
    if (!value) continue;
    if (key === '性别' || key === 'gender') attrs.gender = value;
    else if (key === '年龄' || key === 'age') attrs.age = value;
    else if (key === '职业' || key === '身份' || key === '形态' || key === 'variant') attrs.variant = value;
  }
  return { name, attrs };
}

/** 扫描整条消息里的所有路人标签（去重同名） */
export function scanNormalTags(text: string): { name: string; attrs: NormalAttrs }[] {
  const seen = new Set<string>();
  const out: { name: string; attrs: NormalAttrs }[] = [];
  for (const match of text.matchAll(NORMAL_SCAN_RE)) {
    const parsed = parseNormalTag(match[1]);
    if (parsed && !seen.has(parsed.name)) {
      seen.add(parsed.name);
      out.push(parsed);
    }
  }
  return out;
}

// ── 洗牌袋抽取（候选链封装，核心见 attrPoolCore）──

function normalBucketOf(asset: AttrAssetLike): string {
  return `${asset.cls}|${asset.gender}|${asset.age}|${asset.variant}`;
}

/** 职业/身份模糊匹配：互相包含即命中（"药铺掌柜" ⊆ "药铺掌柜坐堂大夫"） */
function fuzzyVariant(assetVariant: string, want: string): boolean {
  if (assetVariant === want) return true;
  return assetVariant.includes(want) || want.includes(assetVariant);
}

function normalCandidates(attrs: NormalAttrs) {
  return (pool: AttrAssetLike[]): AttrAssetLike[] | undefined => {
    const { gender, age, variant } = attrs;
    if (variant) {
      // 职业优先：同职业+性别+年龄 → 同职业+性别（放宽年龄）；职业存在就绝不跨职业
      let candidates = pool.filter(a =>
        fuzzyVariant(a.variant, variant) && (!gender || a.gender === gender) && (!age || a.age === age));
      if (candidates.length > 0) return candidates;
      candidates = pool.filter(a => fuzzyVariant(a.variant, variant) && (!gender || a.gender === gender));
      return candidates.length > 0 ? candidates : undefined;
    }
    // 未声明职业/身份 → A1 路人矩阵按性别+年龄抽（专职的无名路人库）
    return pool.filter(a =>
      a.cls === 'A1' && (!gender || a.gender === gender) && (!age || a.age === age));
  };
}

/**
 * 确保实例已绑定路人图（幂等）。新绑定 → 抽图并记入登记表。
 * 职业声明了但池中不存在 → 返回 undefined（不配图，文图一致性优先）。
 */
export function ensureNormalBindingOp(
  registry: NormalRegistry,
  instanceName: string,
  attrs: NormalAttrs,
  boundAt: string,
): { registry: NormalRegistry; binding: NormalBinding | undefined; created: boolean } {
  return drawAttrBindingOp(NORMAL_POOL, registry, instanceName, boundAt, normalCandidates(attrs), normalBucketOf);
}
