/**
 * 查询某日探案历注（值神 + 之性 + 行规则）。
 * 世界书条目与 CalendarModal 玩家侧详情共用同一份——AI 看到的攻略玩家也看得到。
 * @param year 公历年
 */
export function getAlmanacGuidance(year: number, month: number, day: number): { god: string; nature: string; rules: string[] } {
  const yiJi = getDailyYiJi(year, month, day);
  return {
    god: yiJi.god,
    nature: ALMANAC_GOD_NATURE[yiJi.god] ?? '',
    rules: ALMANAC_CASE_RULES[yiJi.god] ?? [],
  };
}

/**
 * 生成「黄历_今日」条目内容（纯函数，本地计算）。
 * 结构：日期行（农历+干支+节气/节日）→ 值神宜忌 → 之性 → 当日探案历注 → 宿犯 → 总则。
 * @param tabooCount 未消解犯忌数（因果账，来自 stat_data.因果.犯忌；>0 时输出宿犯行）
 */
export function buildAlmanacContent(gt: GameTime, tabooCount = 0): string {
  const year = eraYearToSolarYear(gt.eraYear);
  const lunar = solarToLunar(year, gt.month, gt.day);
  const dayGanZhi = getDayGanZhi(year, gt.month, gt.day);
  const solarTerm = findSolarTerm(year, gt.month, gt.day);
  const festival = findFestival(year, gt.month, gt.day);
  const yiJi = getDailyYiJi(year, gt.month, gt.day);

  const lines: string[] = [];
  lines.push('<almanac>');
  const lunarText = lunar ? `${lunar.monthName}${lunar.dayName}` : '';
  const ganzhiText = `${getYearGanZhi(year)}${dayGanZhi.gan}${dayGanZhi.zhi}日`;
  lines.push(`日期: 永安${gt.eraYear}年${gt.month}月${gt.day}日（${[lunarText, ganzhiText].filter(Boolean).join('，')}）`);
  if (solarTerm) lines.push(`节令: ${solarTerm.name}，${solarTerm.desc}`);
  if (festival) lines.push(`节庆: ${festival.name}，${festival.desc}`);
  lines.push(`值神: ${yiJi.god}日`);
  lines.push(`宜: ${yiJi.yi.join('、')}`);
  lines.push(`忌: ${yiJi.ji.join('、')}`);
  lines.push(`之性: ${ALMANAC_GOD_NATURE[yiJi.god] ?? ''}`);
  const rules = ALMANAC_CASE_RULES[yiJi.god] ?? [];
  if (rules.length > 0) {
    lines.push('历注:');
    for (const rule of rules) lines.push('  ' + rule.replace('：', ': '));
  }
  if (tabooCount > 0) lines.push(`宿犯: ${tabooCount} 笔`);
  lines.push('</almanac>');

  return lines.join('\n');
}

/* ------------------------------------------------------------------ *
 * 昼夜交替：按节气的日出日入（华北平原口径，游戏粒度到半小时）
 * ------------------------------------------------------------------ */

/** 各节气日出/日入时刻（24h 制小时；日出至夏至递减、日入至夏至递增，冬至昼短夏至昼长） */
const TERM_DAYLIGHT: Record<string, [number, number]> = {
  '小寒': [7.5, 17.5], '大寒': [7.5, 18.0], '立春': [7.0, 18.0], '雨水': [6.5, 18.5],
  '惊蛰': [6.5, 18.5], '春分': [6.0, 18.0], '清明': [6.0, 18.5], '谷雨': [5.5, 19.0],
  '立夏': [5.0, 19.0], '小满': [5.0, 19.5], '芒种': [5.0, 19.5], '夏至': [5.0, 19.5],
  '小暑': [5.0, 19.5], '大暑': [5.5, 19.0], '立秋': [5.5, 19.0], '处暑': [6.0, 18.5],
  '白露': [6.0, 18.5], '秋分': [6.0, 18.0], '寒露': [6.5, 17.5], '霜降': [7.0, 17.0],
  '立冬': [7.0, 17.0], '小雪': [7.5, 17.0], '大雪': [7.5, 17.0], '冬至': [7.5, 17.0],
};

/**
 * 当前节气的日出/日入时刻（小时，可为 .5）。
 * 节气日期按真历，一档约 15 天；岁首小寒之前沿用冬至档。
 */
export function getSunriseSunset(gt: GameTime): { sunrise: number; sunset: number } {
  const year = eraYearToSolarYear(gt.eraYear);
  try {
    const terms = getSolarTermsForYear(year);
    let cur: SolarTermInfo | undefined;
    for (const t of terms) {
      if (gt.month > t.month || (gt.month === t.month && gt.day >= t.day)) cur = t;
    }
    const name = cur?.name ?? '冬至';
    const pair = TERM_DAYLIGHT[name] ?? [6, 18];
    return { sunrise: pair[0], sunset: pair[1] };
  } catch {
    return { sunrise: 6, sunset: 18 };
  }
}

/** 昼夜判定：日入后至日出前为夜（场景 CG 选图与色调联动共用此口径） */
export function getDayNight(gt: GameTime): 'day' | 'night' {
  const { sunrise, sunset } = getSunriseSunset(gt);
  return gt.hour >= sunset || gt.hour < sunrise ? 'night' : 'day';
}
