export const ManualModal: React.FC<ManualModalProps> = ({ isOpen, onClose }) => {
  const [tab, setTab] = useState<'hud' | 'text' | 'investigation' | 'almanac' | 'faq'>('hud');

  const TABS = [
    { id: 'hud' as const, label: '案牍·正文', icon: ScrollText },
    { id: 'investigation' as const, label: '探案', icon: Search },
    { id: 'almanac' as const, label: '天时·舆图·雅乐', icon: Compass },
    { id: 'faq' as const, label: 'FAQ', icon: HelpCircle },
  ];

  // 根据 tab 筛选要显示的 sections
  const getVisibleSections = (): SectionType[] => {
    if (tab === 'hud') return SECTIONS.slice(0, 2); // HUD + 正文
    if (tab === 'investigation') return SECTIONS.slice(2, 3); // 探案
    if (tab === 'almanac') return SECTIONS.slice(3, 6); // 通书 + 舆图 + 雅乐
    if (tab === 'faq') return SECTIONS.slice(6); // 设置 + 教程 + FAQ
    return SECTIONS;
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="大 雍 异 闻 通 鉴 · 卷 宗 指 南" id="manual-modal">
      <div className="flex flex-col gap-5 text-paper-100">
        {/* 顶部选项卡 */}
        <div className="flex gap-2 overflow-x-auto hide-scrollbar border-b border-gold-850 pb-2 shrink-0">
          {TABS.map((item) => {
            const Icon = item.icon;
            const active = tab === item.id;
            return (
              <button
                key={item.id}
                id={`btn-manual-tab-${item.id}`}
                onClick={() => setTab(item.id)}
                className={cn(
                  "flex items-center gap-1.5 px-2.5 sm:px-3 py-1.5 text-xs font-serif rounded-xs border transition-all cursor-pointer whitespace-nowrap shrink-0",
                  active
                    ? "bg-gold-850 text-gold-300 border-gold-500 font-bold shadow-sm"
                    : "bg-ink-750 text-paper-500 border-gold-850 hover:text-paper-50 hover:bg-ink-800"
                )}
              >
                <Icon size={14} />
                <span>{item.label}</span>
              </button>
            );
          })}
        </div>

        {/* 内容区 */}
        <div className="space-y-4 max-h-[65vh] overflow-y-auto custom-scrollbar pr-1">
          {getVisibleSections().map((section, idx) => (
            <div key={idx} className={cn("border overflow-hidden rounded-xs", section.color)}>
              {/* 章节标题 */}
              <div className={cn("flex items-center gap-2 px-3 py-2 font-serif font-bold text-sm", section.color)}>
                {section.icon}
                {section.title}
              </div>

              {/* 章节介绍 */}
              {section.intro && (
                <div className="px-3 py-1.5 bg-ink-900/60 text-xs text-paper-400 border-b border-gold-850/50">
                  {section.intro}
                </div>
              )}

              {/* 子分组 */}
              {section.subGroups && (
                <div className="divide-y divide-gold-850/40">
                  {section.subGroups.map((sub, si) => (
                    <div key={si}>
                      <div className="px-3 py-1.5 bg-ink-800/60 text-xs font-bold text-gold-400 border-b border-gold-850/40">
                        {sub.title}
                      </div>
                      <div className="divide-y divide-gold-850/20">
                        {sub.items.map((item, i) => (
                          <div key={i} className="flex items-start gap-3 px-3 py-2 hover:bg-ink-750/50 transition-colors">
                            <span className="shrink-0 min-w-14 text-xs font-bold bg-ink-850 text-gold-300 px-2 py-0.5 rounded-xs text-center border border-gold-850/50">
                              {item.key}
                            </span>
                            <span className="text-sm text-paper-300 leading-relaxed flex-1 whitespace-pre-line">
                              {item.desc}
                            </span>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              )}

              {/* 普通列表 */}
              {section.items && (
                <div className="divide-y divide-gold-850/20">
                  {section.items.map((item, i) => (
                    <div key={i} className="flex items-start gap-3 px-3 py-2 hover:bg-ink-750/50 transition-colors">
                      <span className="shrink-0 min-w-14 text-xs font-bold bg-ink-850 text-gold-300 px-2 py-0.5 rounded-xs text-center border border-gold-850/50">
                        {item.key}
                      </span>
                      <span className="text-sm text-paper-300 leading-relaxed flex-1 whitespace-pre-line">
                        {item.desc}
                      </span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))}
        </div>

        {/* 底部强调 */}
        <div className="shrink-0 border-t-2 border-gold-850 bg-vermilion-950/30 p-3">
          <p className="text-center text-sm md:text-base font-serif font-bold text-vermilion-300 leading-relaxed">
            ⚠️ 不看说明书反复问问题，案情线索可能被暗流销毁
          </p>
          <div className="flex justify-end mt-2">
            <button
              onClick={onClose}
              className="px-6 py-1.5 bg-ink-850 text-gold-300 text-sm font-serif font-bold hover:bg-gold-850 hover:text-paper-50 transition-colors border border-gold-700 rounded-xs tracking-widest"
            >
              知 道 了
            </button>
          </div>
        </div>
      </div>
    </Modal>
  );
};
