/** 游戏内时间（MVU stat_data.时间；读取与回退见 utils/mvu.ts） */
export interface GameTime {
  eraYear: number;
  month: number;
  day: number;
  hour: number;
  minute: number;
}

/** 从游戏时间派生时间戳字符串（案卷/线索 createdAt 用） */
function formatGameTimestamp(gt: GameTime): string {
  return `永安${gt.eraYear}年 ${gt.month}月${gt.day}日 ${hourToShichen(gt.hour)}`;
}

export type ClueType = 'clue' | 'inference' | 'deduction';

/** 线索来源四类：勘验/文书为硬证据（即确立），证言/传闻为软信息（须坐实） */
export type ClueSource = '勘验' | '证言' | '文书' | '传闻';

/** 推论三轴线：手法/动机/身份（超自然案件中手法与动机优先于身份） */
export type DeductionType = 'how' | 'why' | 'who';

/** 每幕（每条AI消息）可收录的线索上限 */
export const CLUES_PER_FLOOR = 3;

/** 案由四路：诏令（帝）/差事（舅父）/风闻（坊间传闻）/私查（自访） */
export type CaseOrigin = '诏令' | '差事' | '风闻' | '私查';

/**
 * 推论真伪的隐藏判定（由副API在生成候选时给出，玩家不可见）：
 * - 'true'  直接成立的关联 → 视为已确立事实
 * - 'half'  半真，另有隐情 → 待验，可部分印证但保留反转
 * - 'false' 表面合理实为误导 → 待验，AI 应渐进安排反证
 * undefined（玩家手书/编辑）→ 待验
 */
export type TruthTag = 'true' | 'half' | 'false';

/** 案件状态 */
export type CaseStatus = 'active' | 'closed';

/** 案件信息 */
export interface CaseInfo {
  id: string;
  name: string;
  status: CaseStatus;
  keywords: string[];
  closingStatement?: string;
  createdAt: string;
  /** 案由四路：诏令/差事/风闻/私查（决定 AI 叙事的压力色调） */
  origin?: CaseOrigin;
}

export interface Clue {
  id: string;
  title?: string;
  text: string;
  type: ClueType;
  timestamp: string;
  source: string;
  position?: { x: number, y: number };
  /** 所属案件 ID */
  caseId: string;
  /** 线索来源类别（勘验/文书=硬证据；证言/传闻=软信息须坐实；缺省按硬证据对待，兼容旧存档） */
  category?: ClueSource;
  /** 软信息是否已坐实（得到物证或第二来源印证）；硬证据恒为 true */
  verified?: boolean;
  /** 推断或推论的源素材 ID 列表（仅 type='inference' 或 'deduction' 时有效） */
  sourceClueIds?: string[];
  /** 隐藏真伪判定（推断与推论有效；玩家界面不渲染，只进世界书 AI 专属区） */
  truth?: TruthTag;
  /** 真伪状态标记（玩家可见；推断与推论通用） */
  status?: 'pending' | 'true' | 'false';
  /** 收录时所在的楼层（场面制配额追踪；旧存档无此字段时不限） */
  floorId?: number;
  /** 推论轴线类型（仅 type='deduction' 时有效） */
  deductionType?: DeductionType;
}

