const GameContext = createContext<GameContextProps | undefined>(undefined);

/** 聊天变量中的线索存储键 */
const CLUES_STORAGE_KEY = 'mirageClues';

/** 从聊天变量读取持久化数据 */
function loadChatData(): { playerName?: string; clues?: Clue[]; clueConnections?: [string, string][]; cases?: CaseInfo[]; poolRegistry?: PoolRegistry; evilRegistry?: EvilRegistry; normalRegistry?: NormalRegistry } | null {
  try {
    const chatVars = getVariables({ type: 'chat' }) as any;
    if (!chatVars) return null;
    return {
      playerName: typeof chatVars.playerName === 'string' ? chatVars.playerName : undefined,
      clues: Array.isArray(chatVars[CLUES_STORAGE_KEY]?.clues) ? chatVars[CLUES_STORAGE_KEY].clues : undefined,
      clueConnections: Array.isArray(chatVars[CLUES_STORAGE_KEY]?.connections) ? chatVars[CLUES_STORAGE_KEY].connections : undefined,
      cases: Array.isArray(chatVars[CLUES_STORAGE_KEY]?.cases) ? chatVars[CLUES_STORAGE_KEY].cases : undefined,
      poolRegistry: loadPoolRegistry(chatVars),
      evilRegistry: loadEvilRegistry(chatVars),
      normalRegistry: loadNormalRegistry(chatVars),
    };
  } catch {
    return null;
  }
}

/** 获取最新 assistant 楼层号 */
function getLatestAssistantId(): number | null {
  try {
    const lastId = getLastMessageId();
    if (lastId == null) return null;
    const msg = getChatMessages(lastId)[0];
    if (!msg) return null;
    if (msg.role === 'assistant') return msg.message_id;
    if (lastId > 0) {
      const prev = getChatMessages(lastId - 1)[0];
      if (prev && prev.role === 'assistant') return prev.message_id;
    }
    return null;
  } catch {
    return null;
  }
}

/** 生成随机 ID */
function genId(): string {
  return Math.random().toString(36).substring(2, 9);
}

/** 获取游戏内时间戳（从 MVU stat_data.时间 派生，MVU 未就绪时回退占位值） */
function getGameTimestamp(): string {
  return formatGameTimestamp(readGameTime());
}

/**
 * 从 AI 响应中解析推论候选：
 * 优先解析 {"options":[{text,tag}]} 结构化 JSON；
 * 失败则按行拆分（去掉编号前缀），全部视为 half（半真待验）。
 */
function parseInferenceOptions(raw: string): { text: string; truth: TruthTag }[] {
  const normalizeTag = (tag: unknown): TruthTag => (tag === 'true' || tag === 'false' ? tag : 'half');

  // 尝试直接解析，或提取第一个平衡的 JSON 对象
  const jsonCandidates: string[] = [raw];
  const first = raw.indexOf('{');
  const last = raw.lastIndexOf('}');
  if (first >= 0 && last > first) jsonCandidates.push(raw.slice(first, last + 1));

  for (const candidate of jsonCandidates) {
    try {
      const parsed = JSON.parse(candidate);
      const arr = Array.isArray(parsed?.options) ? parsed.options : Array.isArray(parsed) ? parsed : null;
      if (arr) {
        const options = arr
          .map((o: any) => ({ text: String(o?.text ?? o ?? '').trim(), truth: normalizeTag(o?.tag) }))
          .filter((o: { text: string }) => o.text)
          .slice(0, 3);
        if (options.length > 0) return options;
      }
    } catch { /* 继续尝试 */ }
  }

  // 降级：按行拆分
  const lines = raw.split(/\n/).map(s => s.trim().replace(/^\d+[.、)]\s*/, '')).filter(s => s);
  return lines.slice(0, 3).map(text => ({ text, truth: 'half' as TruthTag }));
}

export const GameProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [currentScreen, setCurrentScreen] = useState<Screen>('main-menu');
  const [galleryTab, setGalleryTab] = useState<'characters' | 'character_cg' | 'location_cg'>('characters');
  const [notifications, setNotifications] = useState<NotificationType[]>([]);
  const [clues, setClues] = useState<Clue[]>([]);
  const [cases, setCases] = useState<CaseInfo[]>([]);
  const [clueConnections, setClueConnections] = useState<[string, string][]>([]);
  const [isInvestigating, setIsInvestigating] = useState(false);
  const [viewingFloorId, setViewingFloorId] = useState<number | null>(null);
  const [lastAssistantFloorId, setLastAssistantFloorId] = useState<number | null>(0);
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatingFloorId, setGeneratingFloorId] = useState<number | null>(null);
  const [isCombining, setIsCombining] = useState(false);

  // ── 剧本播放状态 ──
  const [playerName, setPlayerNameState] = useState<string | undefined>(undefined);
  const [pendingMessage, setPendingMessage] = useState<string | null>(null);
  const [scriptCharacterLocations, setScriptCharacterLocations] = useState<Record<string, string>>({});
  const [gameTime, setGameTime] = useState<number>(12);
  const [gameDateTime, setGameDateTime] = useState<GameTime>(() => readGameTime());
  const [weather, setWeatherState] = useState<WeatherType>(() => getDefaultWeather(readGameTime()));
  const [weatherLog, setWeatherLog] = useState<WeatherLogEntry[]>(() => loadWeatherLog());
  const [weatherParticlesEnabled, setWeatherParticlesEnabled] = useState<boolean>(true);
  const [effectsEnabled, setEffectsEnabled] = useState<boolean>(true);
  const [storyVersion, setStoryVersion] = useState(0);
  const [poolRegistry, setPoolRegistry] = useState<PoolRegistry>(EMPTY_POOL_REGISTRY);
  const [evilRegistry, setEvilRegistry] = useState<EvilRegistry>(EMPTY_EVIL_REGISTRY);
  const [normalRegistry, setNormalRegistry] = useState<NormalRegistry>(EMPTY_NORMAL_REGISTRY);

  // ── NSFW CG 自动模式状态 ──
  const [nsfwCgUrl, setNsfwCgUrl] = useState<string | null>(null);

  const isViewingHistory = viewingFloorId !== null;

  // 直接复用 stable setter，避免每轮重建包装函数导致消费方重渲染
  const setViewingFloor = setViewingFloorId;

  // ── state 的 ref 镜像 ──
  const cluesRef = useRef<Clue[]>([]);
  const clueConnectionsRef = useRef<[string, string][]>([]);
  const casesRef = useRef<CaseInfo[]>([]);
  const lastAssistantFloorIdRef = useRef<number | null>(0);
  const poolRegistryRef = useRef<PoolRegistry>(EMPTY_POOL_REGISTRY);
  const evilRegistryRef = useRef<EvilRegistry>(EMPTY_EVIL_REGISTRY);
  const normalRegistryRef = useRef<NormalRegistry>(EMPTY_NORMAL_REGISTRY);
  const weatherRef = useRef<WeatherType>(weather);
  const gameDateTimeRef = useRef<GameTime>(gameDateTime);

  // ── 聊天数据加载 ──
  const loadChatDataIntoState = useCallback(() => {
    const data = loadChatData();
    if (!data) return;
    setPlayerNameState(data.playerName);
    if (data.clues && data.clues.length > 0) {
      cluesRef.current = data.clues;
      setClues(data.clues);
    }
    if (data.clueConnections) {
      clueConnectionsRef.current = data.clueConnections;
      setClueConnections(data.clueConnections);
    }
    if (data.cases && data.cases.length > 0) {
      casesRef.current = data.cases;
      setCases(data.cases);
    }
    if (data.poolRegistry && Object.keys(data.poolRegistry.bindings).length > 0) {
      poolRegistryRef.current = data.poolRegistry;
      setPoolRegistry(data.poolRegistry);
    }
    if (data.evilRegistry && Object.keys(data.evilRegistry.bindings).length > 0) {
      evilRegistryRef.current = data.evilRegistry;
      setEvilRegistry(data.evilRegistry);
    }
    if (data.normalRegistry && Object.keys(data.normalRegistry.bindings).length > 0) {
      normalRegistryRef.current = data.normalRegistry;
      setNormalRegistry(data.normalRegistry);
    }
  }, []);

  useEffect(() => {
    loadChatDataIntoState();
    // 黄历条目：确保「黄历_今日」蓝灯条目与当前游戏日期一致（幂等，日期未变时零开销；
    // 时间源为 MVU stat_data.时间，MVU 未就绪时回退本地占位值）
    ensureAlmanacEntry(readGameTime()).catch(e => {
      console.warn('[幻璃镜] 黄历条目初始化失败:', e);
    });
    ensureTeahouseEntry(readGameTime()).catch(e => {
      console.warn('[幻璃镜] 茶楼条目初始化失败:', e);
    });
    ensureWeatherEntry(weatherRef.current).catch(e => {
      console.warn('[幻璃镜] 天象条目初始化失败:', e);
    });
    initMvuPipeline().catch(e => {
      console.warn('[幻璃镜] MVU 初始化失败:', e);
    });
    try {
      const stop = eventOn(tavern_events.CHAT_CHANGED, () => {
        loadChatDataIntoState();
        ensureAlmanacEntry(readGameTime()).catch(e => {
          console.warn('[幻璃镜] 黄历条目同步失败:', e);
        });
        ensureTeahouseEntry(readGameTime()).catch(e => {
          console.warn('[幻璃镜] 茶楼条目同步失败:', e);
        });
        ensureWeatherEntry(weatherRef.current).catch(e => {
          console.warn('[幻璃镜] 天象条目同步失败:', e);
        });
        initMvuPipeline().catch(e => {
          console.warn('[幻璃镜] MVU 随聊天切换初始化失败:', e);
        });
        setLastAssistantFloorId(getLatestAssistantId());
        setViewingFloorId(null);
      });
      return () => {
        if (stop?.stop) stop.stop();
      };
    } catch (e) {
      console.warn('[幻璃镜] CHAT_CHANGED 监听注册跳过:', e);
      return undefined;
    }
  }, [loadChatDataIntoState]);

  const setPlayerName = useCallback((name: string | undefined) => {
    const trimmed = name?.trim() || undefined;
    setPlayerNameState(trimmed);
    try {
      updateVariablesWith(vars => ({ ...vars, playerName: trimmed ?? '' }), { type: 'chat' });
      console.info('[幻璃镜] 玩家名已设置:', trimmed ?? '(清空)');
    } catch {
      console.warn('[幻璃镜] 无法持久化玩家名到聊天变量');
    }
  }, []);

  /** 持久化到聊天变量 */
  const persistAll = useCallback((nextClues: Clue[], nextConnections: [string, string][], nextCases: CaseInfo[]) => {
    try {
      updateVariablesWith(
        vars => ({ ...vars, [CLUES_STORAGE_KEY]: { clues: nextClues, connections: nextConnections, cases: nextCases } }),
        { type: 'chat' },
      );
    } catch {
      console.warn('[幻璃镜] 无法持久化线索卷宗到聊天变量');
    }
  }, []);



  /** 同时更新 React state 和聊天变量 */
  const updateCluesAndCases = useCallback((cluesUpdater: (prev: Clue[]) => Clue[], connectionsUpdater?: (prev: [string, string][]) => [string, string][], casesUpdater?: (prev: CaseInfo[]) => CaseInfo[]) => {    const nextClues = cluesUpdater(cluesRef.current);
    const nextConn = connectionsUpdater ? connectionsUpdater(clueConnectionsRef.current) : clueConnectionsRef.current;
    const nextCases = casesUpdater ? casesUpdater(casesRef.current) : casesRef.current;
    cluesRef.current = nextClues;
    clueConnectionsRef.current = nextConn;
    casesRef.current = nextCases;
    setClues(nextClues);
    setClueConnections(nextConn);
    setCases(nextCases);
    persistAll(nextClues, nextConn, nextCases);
  }, [persistAll]);

  const startGenerating = useCallback((floorId?: number) => {
    const lockFloor = floorId ?? viewingFloorId ?? lastAssistantFloorId;
    if (lockFloor != null) setViewingFloor(lockFloor);
    setIsGenerating(true);
    console.info('[幻璃镜] 开始生成，锁定画面到楼层', lockFloor);
  }, [viewingFloorId, lastAssistantFloorId]);

  const finishGenerating = useCallback(() => {
    setIsGenerating(false);
    const newFloorId = getLatestAssistantId();
    if (newFloorId != null) {
      setGeneratingFloorId(newFloorId);
      setLastAssistantFloorId(newFloorId);
    }
    // 生成完成后解除画面锁定 → 自动跟随最新楼层，正文立即切换到新楼层内容
    setViewingFloorId(null);
    console.info('[幻璃镜] 生成完成，最新 assistant 楼层:', newFloorId, '— 已自动切回跟随最新');
  }, []);

  // ── 楼层同步 ──
  const isGeneratingRef = useRef(isGenerating);
  const generatingFloorIdRef = useRef(generatingFloorId);
  isGeneratingRef.current = isGenerating;
  generatingFloorIdRef.current = generatingFloorId;
  weatherRef.current = weather;
  gameDateTimeRef.current = gameDateTime;
  lastAssistantFloorIdRef.current = lastAssistantFloorId;

  useEffect(() => {
    const syncLatestFloor = () => {
      const latestId = getLatestAssistantId();
      if (latestId == null) return;
      if (isGeneratingRef.current) {
        if (generatingFloorIdRef.current == null || latestId > generatingFloorIdRef.current) {
          setGeneratingFloorId(latestId);
        }
      } else {
        setLastAssistantFloorId(prev => (prev === latestId ? prev : latestId));
      }
    };

    const stops: (() => void)[] = [];
    const register = (ret: EventOnReturn | undefined) => {
      if (ret?.stop) stops.push(() => ret.stop?.());
    };
    register(eventOn(tavern_events.MESSAGE_RECEIVED, () => {
      syncLatestFloor();
    }));
    register(eventOn(tavern_events.MESSAGE_UPDATED, () => {
      syncLatestFloor();
      setStoryVersion(v => v + 1);
    }));
    register(eventOn(iframe_events.GENERATION_ENDED, () => {
      setTimeout(syncLatestFloor, 300);
      // 生成结束后 bump storyVersion，驱动 HUD 时间/地点等依赖 storyVersion 的 memo 重算
      setStoryVersion(v => v + 1);
      // ── 天气演变：AI 正文回写优先，否则马尔可夫滚动 ──
      setTimeout(() => {
        try {
          const latestId = getLatestAssistantId();
          let next: WeatherType = weatherRef.current;
          if (latestId != null) {
            const msg = getChatMessages(latestId)[0];
            if (msg) {
              const extracted = extractWeatherFromText(msg.message);
              if (extracted) {
                next = extracted;
              } else {
                next = rollWeather(weatherRef.current, gameDateTimeRef.current, latestId);
              }
            }
          }
          if (next !== weatherRef.current) {
            weatherRef.current = next;
            setWeatherState(next);
            const entry: WeatherLogEntry = {
              weather: next,
              floorId: latestId,
              seq: Date.now(),
            };
            const updated = appendWeatherLog(entry);
            setWeatherLog(updated);
            // 天象条目随天气变化重写（幂等，天气未变时零开销）
            ensureWeatherEntry(next).catch(e => {
              console.warn('[幻璃镜] 天象条目更新失败:', e);
            });
          }
        } catch {
          // 天气演变失败不影响主流程
        }
      }, 400);
      // ── 不言生故事提取：<storytale> 标记块 → 写入对应案件的不言生条目 ──
      setTimeout(() => {
        try {
          const latestId = getLatestAssistantId();
          if (latestId == null) return;
          const msg = getChatMessages(latestId)[0];
          if (!msg) return;
          const tales = extractStorytales(msg.message);
          if (tales.length === 0) return;
          // 有故事标记块：写入当前 active 案件（或最近一个案件）
          const activeCase = casesRef.current.find(c => c.status === 'active')
            ?? casesRef.current[casesRef.current.length - 1];
          if (!activeCase) {
            console.warn('[幻璃镜] 提取到不言生故事但无案件可关联');
            return;
          }
          appendStorytalesToCase(activeCase.id, activeCase.name, tales, false).catch(e => {
            console.warn('[幻璃镜] 不言生故事写入失败:', e);
          });
        } catch {
          // 故事提取失败不影响主流程
        }
      }, 500);
    }));
    register(eventOn('mirage_story_updated', () => {
      syncLatestFloor();
      setStoryVersion(v => v + 1);
    }));

    syncLatestFloor();

    return () => {
      stops.forEach(stop => stop());
    };
  }, []);

  // ── 通知系统（记忆化，避免 value 每轮重建拖累所有消费方）──
  const notificationTimersRef = useRef<ReturnType<typeof setTimeout>[]>([]);

  const removeNotification = useCallback((id: string) => {
    setNotifications((prev) => prev.filter((n) => n.id !== id));
  }, []);

  const addNotification = useCallback((message: string, type: 'info' | 'warning' | 'success' = 'info') => {
    const id = genId();
    setNotifications((prev) => [...prev, { id, message, type }]);
    const timer = setTimeout(() => {
      removeNotification(id);
      notificationTimersRef.current = notificationTimersRef.current.filter(t => t !== timer);
    }, 4000);
    notificationTimersRef.current.push(timer);
  }, [removeNotification]);

  // 卸载时清理所有未触发的通知定时器
  useEffect(() => {
    return () => {
      notificationTimersRef.current.forEach(t => clearTimeout(t));
      notificationTimersRef.current = [];
    };
  }, []);

  // ── MVU 接入：stat_data（时间/地点/暗流/因果）──
  // （置于 addNotification 之后声明，犯忌提醒要用通知）
  const mvuListenerRef = useRef(false);
  const lastTabooRef = useRef(0);
  const syncTimeFrom = useCallback((gt: GameTime) => {
    gameDateTimeRef.current = gt;
    setGameDateTime(gt);
    // 日期键在 ensureAlmanacEntry 内部把关：时间没变零开销，跨日自动翻页
    ensureAlmanacEntry(gt).catch(e => console.warn('[幻璃镜] 历注随时间刷新失败:', e));
    ensureTeahouseEntry(gt).catch(e => console.warn('[幻璃镜] 茶楼随时间刷新失败:', e));
  }, []);
  const syncTimeFromMvu = useCallback(() => syncTimeFrom(readGameTime()), [syncTimeFrom]);
  const initMvuPipeline = useCallback(async () => {
    const ready = await ensureMvuReady(8000);
    if (!ready) {
      console.info('[幻璃镜] MVU 框架未就绪，时间/暗流以本地模式运行');
      return;
    }
    // MVU 接线条目（initvar/更新规则/输出格式/变量列表）随角色卡世界书发布，前端不写世界书
    await seedStatDataIfMissing();
    syncTimeFromMvu();
    if (!mvuListenerRef.current) {
      mvuListenerRef.current = true;
      // 变量更新结束（官方范式：直接改写传入的 variables，框架随后落盘）：
      // 夹逼数值 → 暗流非案件锁定 → 同步时间/历注/翻案 → 天象时辰 → 犯忌提醒
      onVariableUpdateEnded((variables, _variablesBefore) => {
        clampStatNumbers(variables);
        // 无活跃案件时锁定暗流为空
        const hasActiveCase = casesRef.current.some(c => c.status === 'active');
        if (!hasActiveCase && variables?.stat_data?.暗流 && Object.keys(variables.stat_data.暗流).length > 0) {
          variables.stat_data.暗流 = {};
        }
        syncTimeFrom(readGameTime());
        ensureWeatherEntry(weatherRef.current).catch(() => {});
        const sd = variables?.stat_data ?? null;
        const taboo = readTabooCount(sd);
        if (taboo > lastTabooRef.current) {
          addNotification(taboo >= 3 ? '异象渐生——你身上犯忌之数已重' : '违忌之事，因果记账', 'warning');
        }
        lastTabooRef.current = taboo;
      });
    }
  }, [syncTimeFrom, syncTimeFromMvu]);

  /**
   * 随机宅邸池：确保实例已绑定图套（幂等）。
   * 新绑定 → 记入存档并轻提示"舆图新录一地"；袋子用尽重洗发生在玩家背后，不提示。
   */
  const ensurePoolBinding = useCallback((instanceName: string, sceneName?: string): PoolBinding | undefined => {
    const activeCase = casesRef.current.find(c => c.status === 'active');
    const { registry, binding, created } = ensurePoolBindingOp(
      poolRegistryRef.current,
      instanceName,
      { sceneName, caseId: activeCase?.id, boundAt: getGameTimestamp() },
    );
    if (!binding) return undefined;
    if (created) {
      poolRegistryRef.current = registry;
      setPoolRegistry(registry);
      try {
        updateVariablesWith(vars => ({ ...vars, [POOL_STORAGE_KEY]: registry }), { type: 'chat' });
      } catch {
        console.warn('[幻璃镜] 无法持久化宅邸池登记表');
      }
      addNotification(`舆图新录一地：${instanceName}`, 'info');
      // 限时地点（宫眷宫室）：额外醒目提示"可调查地点出现"
      if (binding.tier === 'xianshi') {
        addNotification(`✦ 可调查地点出现：${instanceName}`, 'success');
      }
    }
    return binding;
  }, [addNotification]);

  /**
   * 邪异随机池：确保实例已绑定图（幂等）。
   * LLM 打 [邪异:名称,类别=..,性别=..,年龄=..,形态=..] 标签后调用；
   * 新绑定 → 记入存档并轻提示"邪异现形"；性别硬约束，宁可不配图也不配错图。
   */
  const ensureEvilBinding = useCallback((instanceName: string, attrs: EvilAttrs): EvilBinding | undefined => {
    const { registry, binding, created } = ensureEvilBindingOp(
      evilRegistryRef.current,
      instanceName,
      attrs,
      getGameTimestamp(),
    );
    if (!binding) return undefined;
    if (created) {
      evilRegistryRef.current = registry;
      setEvilRegistry(registry);
      try {
        updateVariablesWith(vars => ({ ...vars, [EVIL_STORAGE_KEY]: registry }), { type: 'chat' });
      } catch {
        console.warn('[幻璃镜] 无法持久化邪异池登记表');
      }
      addNotification(`邪异现形：${instanceName}`, 'warning');
    }
    return binding;
  }, [addNotification]);

  /**
   * 路人随机池：确保实例已绑定图（幂等）。
   * LLM 打 [路人:名称,职业=..,性别=..,年龄=..] 标签后调用；
   * 静默绑定不提示（路人出场频繁）；职业不存在时不配图。
   */
  const ensureNormalBinding = useCallback((instanceName: string, attrs: NormalAttrs): NormalBinding | undefined => {
    const { registry, binding, created } = ensureNormalBindingOp(
      normalRegistryRef.current,
      instanceName,
      attrs,
      getGameTimestamp(),
    );
    if (!binding) return undefined;
    if (created) {
      normalRegistryRef.current = registry;
      setNormalRegistry(registry);
      try {
        updateVariablesWith(vars => ({ ...vars, [NORMAL_STORAGE_KEY]: registry }), { type: 'chat' });
      } catch {
        console.warn('[幻璃镜] 无法持久化路人池登记表');
      }
    }
    return binding;
  }, []);

  // ── 案件管理 ──

  /** 创建新案件，返回案件 ID */
  const createCase = useCallback((name: string, origin?: CaseOrigin): string => {
    const caseId = genId();
    const newCase: CaseInfo = {
      id: caseId,
      name: name.trim() || '未命名案件',
      status: 'active',
      keywords: [],
      createdAt: getGameTimestamp(),
      origin,
    };
    updateCluesAndCases(
      prev => prev, // clues 不变
      prev => prev, // connections 不变
      prev => [...prev, newCase],
    );
    // 创建世界书条目（串行：先案件条目，再不言生条目——避免并发 updateWorldbookWith 互覆）
    createCaseEntry(caseId, newCase.name, [], origin)
      .then(() => createStorytaleEntry(caseId, newCase.name))
      .catch(e => {
        console.warn('[幻璃镜] 案件/不言生条目创建失败:', e);
      });
    addNotification(`案件「${newCase.name}」已创建`, 'success');
    console.info('[幻璃镜] 新案件已创建:', caseId, newCase.name);
    return caseId;
  }, [updateCluesAndCases]);

  /** 结案（玩家自己填关键词和结案陈词）；须手法/动机/身份三轴线各有已验证推论方可定谳 */
  const closeCase = useCallback(async (caseId: string, caseName: string, keywords: string[], closingStatement: string): Promise<boolean> => {
    const caseClues = cluesRef.current.filter(c => c.caseId === caseId);
    // 定谳门槛：手法/动机/身份三轴线各至少一条已验证推论（玩家标记属实）
    const verifiedDeductions = caseClues.filter(c => c.type === 'deduction' && c.status === 'true');
    const hasHow = verifiedDeductions.some(d => d.deductionType === 'how');
    const hasWhy = verifiedDeductions.some(d => d.deductionType === 'why');
    const hasWho = verifiedDeductions.some(d => d.deductionType === 'who');
    if (!hasHow || !hasWhy || !hasWho) {
      const missing: string[] = [];
      if (!hasHow) missing.push('手法');
      if (!hasWhy) missing.push('动机');
      if (!hasWho) missing.push('身份');
      addNotification(`定谳不全，尚缺${missing.join('、')}推论`, 'warning');
      return false;
    }
    const caseInfo = casesRef.current.find(c => c.id === caseId);
    const success = await closeCaseEntry(caseId, caseName, keywords, caseClues, closingStatement, caseInfo?.origin);
    // 同步不言生故事条目蓝灯→绿灯
    closeStorytaleEntry(caseId, caseName, keywords).catch(e => {
      console.warn('[幻璃镜] 不言生故事条目结案失败:', e);
    });
    if (success) {
      updateCluesAndCases(
        prev => prev,
        prev => prev,
        prev => prev.map(c => c.id === caseId ? { ...c, status: 'closed', name: caseName, keywords, closingStatement } : c),
      );
      addNotification(`案件「${caseName}」已结案`, 'success');
      // 结案后若无其他活跃案件，清空暗流
      const stillActive = casesRef.current.some(c => c.id !== caseId && c.status === 'active');
      if (!stillActive) {
        clearSuspicion().catch(() => {});
      }
    } else {
      addNotification('结案失败，请检查世界书设置', 'warning');
    }
    return success;
  }, [updateCluesAndCases]);

  /** 重新开启已结案的案件 */
  const reopenCase = useCallback((caseId: string) => {
    updateCluesAndCases(
      prev => prev,
      prev => prev,
      prev => prev.map(c => c.id === caseId ? { ...c, status: 'active' } : c),
    );
    // 更新世界书条目回蓝灯
    const caseInfo = casesRef.current.find(c => c.id === caseId);
    const caseClues = cluesRef.current.filter(c => c.caseId === caseId);
    if (caseInfo) {
      updateCaseEntry(caseId, caseInfo.name, caseClues, false, undefined, caseInfo.origin);
    }
    addNotification('案件已重新开启', 'info');
  }, [updateCluesAndCases]);

  /** 重命名案件（同步更新世界书条目 content，条目名用 caseId 不变） */
  const renameCase = useCallback((caseId: string, newName: string) => {
    const trimmed = newName.trim() || '未命名案件';
    const caseInfo = casesRef.current.find(c => c.id === caseId);
    if (!caseInfo) return;
    const isClosed = caseInfo.status === 'closed';
    updateCluesAndCases(
      prev => prev,
      prev => prev,
      prev => prev.map(c => c.id === caseId ? { ...c, name: trimmed } : c),
    );
    // 同步更新案件条目 content（条目名用 caseId，不需改）
    // 串行：先案件条目，再不言生条目——避免并发 updateWorldbookWith 互覆
    const caseClues = cluesRef.current.filter(c => c.caseId === caseId);
    updateCaseEntry(caseId, trimmed, caseClues, isClosed, caseInfo.closingStatement, caseInfo.origin)
      .then(() => updateStorytaleEntryName(caseId, trimmed, isClosed))
      .catch(e => {
        console.warn('[幻璃镜] 案件/不言生条目改名失败:', e);
      });
    addNotification(`案件已命名为「${trimmed}」`, 'success');
  }, [updateCluesAndCases]);

  /** 删除案件 */
  const deleteCase = useCallback((caseId: string) => {
    // 串行删除：先案件条目，再不言生条目——避免并发 updateWorldbookWith 互覆
    deleteCaseEntry(caseId)
      .then(() => deleteStorytaleEntry(caseId))
      .catch(e => {
        console.warn('[幻璃镜] 案件/不言生条目删除失败:', e);
      });
    updateCluesAndCases(
      prev => prev.filter(c => c.caseId !== caseId),
      prevConn => prevConn.filter(conn => {
        const c1 = cluesRef.current.find(c => c.id === conn[0]);
        const c2 = cluesRef.current.find(c => c.id === conn[1]);
        return c1?.caseId !== caseId && c2?.caseId !== caseId;
      }),
      prev => prev.filter(c => c.id !== caseId),
    );
    addNotification('案件已删除', 'info');
  }, [updateCluesAndCases]);

  /** 获取指定案件的所有线索和推论 */
  const getCaseClues = useCallback((caseId: string): Clue[] => {
    return cluesRef.current.filter(c => c.caseId === caseId);
  }, []);

  // ── 线索/推论管理 ──

  /** 添加线索（录入即待证；坐实走 verifyClue）；场面制：每幕限 CLUES_PER_FLOOR 条 */
  const addClue = useCallback((text: string, source: string, caseId: string, type: ClueType = 'clue', position?: { x: number, y: number }, category?: ClueSource): boolean => {
    if (cluesRef.current.some(c => c.text === text && c.caseId === caseId)) {
      addNotification('该线索已记录', 'warning');
      return false;
    }
    // 场面制配额：同一楼层已收录的线索不得超过上限
    const currentFloor = lastAssistantFloorIdRef.current;
    if (currentFloor != null && type === 'clue') {
      const floorCount = cluesRef.current.filter(c => c.floorId === currentFloor && c.type === 'clue').length;
      if (floorCount >= CLUES_PER_FLOOR) {
        addNotification('此景已尽力记下，再查须待新事态', 'warning');
        return false;
      }
    }
    const newClue: Clue = {
      id: genId(),
      text,
      type,
      timestamp: getGameTimestamp(),
      source,
      position: position || { x: 50 + Math.random() * 200, y: 50 + Math.random() * 200 },
      caseId,
      // 三道闸之二：勘验/文书为硬证据，录入即确立；证言/传闻为软信息，须坐实
      category,
      verified: category === '勘验' || category === '文书',
      floorId: currentFloor ?? undefined,
    };

    // 目标案件不存在时（开局未建案、_temp 等），自动创建「初录案卷」承接，避免线索漏出世界书
    if (!casesRef.current.some(c => c.id === caseId)) {
      const newCaseId = genId();
      const newCase: CaseInfo = {
        id: newCaseId,
        name: '初录案卷',
        status: 'active',
        keywords: [],
        createdAt: getGameTimestamp(),
      };
      // 先更新线索（用 newCaseId 替换 caseId）
      newClue.caseId = newCaseId;
      updateCluesAndCases(
        prev => [...prev, newClue],
        undefined,
        prev => [...prev, newCase],
      );
      // 直接用带线索的 createCaseEntry 创建世界书条目（避免 createCaseEntry 与 updateCaseEntry 竞态）
      // 串行：先案件条目，再不言生条目——避免并发 updateWorldbookWith 互覆
      createCaseEntry(newCaseId, newCase.name, [newClue])
        .then(() => createStorytaleEntry(newCaseId, newCase.name))
        .catch(e => {
          console.warn('[幻璃镜] 初录案卷/不言生条目创建失败:', e);
        });
      addNotification('已自动创建「初录案卷」', 'info');
    } else {
      updateCluesAndCases(prev => [...prev, newClue]);

      // 同步到世界书
      const caseInfo = casesRef.current.find(c => c.id === caseId);
      if (caseInfo) {
        const caseClues = [...cluesRef.current.filter(c => c.caseId === caseId), newClue];
        updateCaseEntry(caseId, caseInfo.name, caseClues, caseInfo.status === 'closed', caseInfo.closingStatement, caseInfo.origin);
      }
    }

    addNotification(`已收集${type === 'deduction' ? '推论' : type === 'inference' ? '推断' : '线索'}`, 'success');
    return true;
  }, [updateCluesAndCases]);

  /** 删除线索/推论 */
  const removeClue = useCallback((id: string) => {
    const clue = cluesRef.current.find(c => c.id === id);
    if (!clue) return;
    const caseId = clue.caseId;

    updateCluesAndCases(
      prev => prev.filter(c => c.id !== id),
      prevConn => prevConn.filter(conn => conn[0] !== id && conn[1] !== id),
    );

    // 同步到世界书
    const caseInfo = casesRef.current.find(c => c.id === caseId);
    if (caseInfo) {
      const caseClues = cluesRef.current.filter(c => c.caseId === caseId && c.id !== id);
      updateCaseEntry(caseId, caseInfo.name, caseClues, caseInfo.status === 'closed', caseInfo.closingStatement, caseInfo.origin);
    }
  }, [updateCluesAndCases]);

  /** 编辑线索/推论文本 */
  const editClue = useCallback((id: string, text: string) => {
    const clue = cluesRef.current.find(c => c.id === id);
    if (!clue) return;
    const caseId = clue.caseId;

    updateCluesAndCases(prev => prev.map(c => c.id === id ? { ...c, text } : c));

    // 同步到世界书
    const caseInfo = casesRef.current.find(c => c.id === caseId);
    if (caseInfo) {
      const caseClues = cluesRef.current.filter(c => c.caseId === caseId).map(c => c.id === id ? { ...c, text } : c);
      updateCaseEntry(caseId, caseInfo.name, caseClues, caseInfo.status === 'closed', caseInfo.closingStatement, caseInfo.origin);
    }
    addNotification('已更新', 'success');
  }, [updateCluesAndCases]);

  /** 更新推断或推论的真伪状态标记（玩家可见） */
  const updateDeductionStatus = useCallback((id: string, status: ClueStatus) => {
    const clue = cluesRef.current.find(c => c.id === id);
    if (!clue) return;
    if (clue.type !== 'inference' && clue.type !== 'deduction') return;
    const caseId = clue.caseId;

    updateCluesAndCases(prev => prev.map(c => c.id === id ? { ...c, status } : c));

    // 同步到世界书
    const caseInfo = casesRef.current.find(c => c.id === caseId);
    if (caseInfo) {
      const caseClues = cluesRef.current.filter(c => c.caseId === caseId).map(c => c.id === id ? { ...c, status } : c);
      updateCaseEntry(caseId, caseInfo.name, caseClues, caseInfo.status === 'closed', caseInfo.closingStatement, caseInfo.origin);
    }
    const typeLabel = clue.type === 'deduction' ? '推论' : '推断';
    const statusLabel = status === 'true' ? '属实' : status === 'false' ? '伪证' : '未定';
    addNotification(`${typeLabel}已标记为「${statusLabel}」`, 'info');
  }, [updateCluesAndCases]);

  /** 更新推论轴线类型（手法/动机/身份） */
  const updateDeductionType = useCallback((id: string, type: DeductionType) => {
    const clue = cluesRef.current.find(c => c.id === id);
    if (!clue || clue.type !== 'deduction') return;
    const caseId = clue.caseId;

    updateCluesAndCases(prev => prev.map(c => c.id === id ? { ...c, deductionType: type } : c));

    const caseInfo = casesRef.current.find(c => c.id === caseId);
    if (caseInfo) {
      const caseClues = cluesRef.current.filter(c => c.caseId === caseId).map(c => c.id === id ? { ...c, deductionType: type } : c);
      updateCaseEntry(caseId, caseInfo.name, caseClues, caseInfo.status === 'closed', caseInfo.closingStatement, caseInfo.origin);
    }
  }, [updateCluesAndCases]);

  /**
   * 调用 AI 生成三条推断或推论选项（每条带隐藏真伪判定）
   * 产出类型由源素材决定：
   * - 全是线索 → 产出推断（初步判断，可真可假）
   * - 含推断或推论 → 产出推论（更高阶结论）
   * 已配置推演副API → generateRaw 独立调用（无主聊天上下文，便宜且不剧透主模型伏笔）
   * 未配置 → 回退主连接 generate()
   */
  const combineClues = useCallback(async (id1: string, id2: string): Promise<{ text: string; truth: TruthTag }[] | false> => {
    const c1 = cluesRef.current.find(c => c.id === id1);
    const c2 = cluesRef.current.find(c => c.id === id2);
    if (!c1 || !c2) return false;

    // 检查是否已经关联过
    const existingConnection = clueConnectionsRef.current.find(
      c => (c[0] === id1 && c[1] === id2) || (c[0] === id2 && c[1] === id1)
    );
    if (existingConnection) {
      addNotification('这两个素材已经关联过了', 'info');
      return false;
    }

    // 产出类型：源素材中含推断或推论 → 推论；全是线索 → 推断
    const hasHigherTier = c1.type === 'inference' || c1.type === 'deduction' || c2.type === 'inference' || c2.type === 'deduction';
    const outputType: ClueType = hasHigherTier ? 'deduction' : 'inference';
    const outputLabel = outputType === 'deduction' ? '推论' : '推断';

    // 案件上下文：案件名 + 当前卷宗摘要（含隐藏判定，副API可信）
    const caseInfo = casesRef.current.find(c => c.id === c1.caseId);
    const caseClues = cluesRef.current.filter(c => c.caseId === c1.caseId);
    const canonLines = caseClues.map(c => {
      if (c.type === 'clue') {
        const tag = c.category ? `[${c.category}${(c.category === '证言' || c.category === '传闻') && c.verified !== true ? '·待证' : ''}]` : '';
        return `线索${tag}：${c.text}`;
      }
      if (c.type === 'inference') {
        const statusDesc = c.status === 'true' ? '（玩家判定属实）' : c.status === 'false' ? '（玩家判定伪证）' : '（未定）';
        return `推断：${c.text}${statusDesc}`;
      }
      const tagDesc = c.truth === 'true' ? '（已证）' : c.truth === 'false' ? '（判定为假）' : c.truth === 'half' ? '（判定半真）' : '';
      const typeDesc = c.deductionType ? `[${c.deductionType === 'how' ? '手法' : c.deductionType === 'why' ? '动机' : '身份'}]` : '';
      return `推论${typeDesc}：${c.text}${tagDesc}`;
    });
    const canonSummary = canonLines.length > 0 ? canonLines.join('\n') : '（暂无线索记录）';

    const materialLabel = (c: Clue) => {
      if (c.type === 'clue') {
        const tag = c.category ? `[${c.category}${(c.category === '证言' || c.category === '传闻') && c.verified !== true ? '·待证' : ''}]` : '';
        return `线索${tag}：${c.text}`;
      }
      if (c.type === 'inference') return `推断：${c.text}`;
      const typeDesc = c.deductionType ? `[${c.deductionType === 'how' ? '手法' : c.deductionType === 'why' ? '动机' : '身份'}]` : '';
      return `推论${typeDesc}：${c.text}`;
    };

    setIsCombining(true);
    const subApi: SubApiConfig = loadSubApi();
    try {
      let raw = '';

      const systemPrompt1 = `你是大雍朝钦天监的探案推演助手。世界观：志怪邪异真实存在，行为各有因果缘由；钦天监懂因果，民间只知禁忌土法。你负责根据玩家收集的素材给出${outputLabel}方向。`;

      const systemPrompt2 = `当前案件《${caseInfo?.name ?? '未命名'}》卷宗：\n${canonSummary}`;

      const userPrompt = outputType === 'inference'
        ? `素材1：${materialLabel(c1)}\n素材2：${materialLabel(c2)}\n\n（素材若带[证言·待证]或[传闻·待证]标记，属未经印证的方向而非事实；以其为主要依据的推断，tag 不得为 true，宜为 half 或 false。）\n\n请根据这两条素材给出三个不同角度的推断方向，三者必须真正分岔：\n- 一条 tag 为 "true"：由两素材直接成立的最顺关联\n- 一条 tag 为 "half"：表面成立但另有隐情，存在第二种解释\n- 一条 tag 为 "false"：表面最合理、实为误导或巧合\ntag 是给系统的隐藏标记，玩家不可见。每条推断简洁有力，是初步判断而非最终结论，指向下一步调查方向。\n只输出JSON，格式：{"options":[{"text":"...","tag":"true"},{"text":"...","tag":"half"},{"text":"...","tag":"false"}]}`
        : `素材1：${materialLabel(c1)}\n素材2：${materialLabel(c2)}\n\n（素材若带[证言·待证]或[传闻·待证]标记，属未经印证的方向而非事实；以其为主要依据的推论，tag 不得为 true，宜为 half 或 false。素材中的推断若被玩家判定伪证，基于它的推论须留更大反转余地。）\n\n请根据这些素材给出三个不同角度的推论方向，三者必须真正分岔：\n- 一条 tag 为 "true"：由素材直接成立的结论\n- 一条 tag 为 "half"：表面成立但另有隐情，存在第二种解释\n- 一条 tag 为 "false"：表面最合理、实为误导或巧合\ntag 是给系统的隐藏标记，玩家不可见。每条推论是一个结论性判断，可指向手法、动机或身份。\n只输出JSON，格式：{"options":[{"text":"...","tag":"true"},{"text":"...","tag":"half"},{"text":"...","tag":"false"}]}`;

      if (isSubApiReady(subApi)) {
        // ── 副 API 路径：独立调用，干净上下文 ──
        const result = await generateRaw({
          should_silence: true,
          max_chat_history: 0,
          custom_api: {
            apiurl: subApi.apiurl || undefined,
            key: subApi.key || undefined,
            model: subApi.model,
            source: subApi.source || 'openai',
            temperature: 0.9,
            max_tokens: 1000,
          },
          ordered_prompts: [
            { role: 'system' as const, content: systemPrompt1 },
            { role: 'system' as const, content: systemPrompt2 },
            { role: 'user' as const, content: userPrompt },
          ],
        });
        raw = typeof result === 'string' ? result.trim() : '';
      } else {
        // ── 回退路径：主连接 ──
        const result = await generate({
          user_input: `${systemPrompt1}\n\n${systemPrompt2}\n\n${userPrompt}`,
          should_stream: false,
          should_silence: true,
        });
        raw = typeof result === 'string' ? result.trim() : '';
      }

      if (!raw) {
        addNotification(`AI 未能生成${outputLabel}`, 'warning');
        return false;
      }

      // 解析：优先结构化 JSON，失败则降级为按行拆分（全部视为 half）
      const options = parseInferenceOptions(raw);
      if (options.length === 0) {
        addNotification(`AI 未能生成${outputLabel}`, 'warning');
        return false;
      }

      console.info(`[幻璃镜] AI 生成的${outputLabel}选项:`, options);
      return options;
    } catch (e) {
      console.error(`[幻璃镜] 调用 AI 生成${outputLabel}失败`, e);
      addNotification(`生成${outputLabel}失败`, 'warning');
      return false;
    } finally {
      setIsCombining(false);
    }
  }, []);

  /** 确认推断或推论（支持任意数量的源素材，也支持玩家手写）；truth 为隐藏判定，deductionType 为推论轴线 */
  /** 坐实待证线索（经正文验证行动后标记），归入已确立事实 */
  const verifyClue = useCallback((id: string) => {
    const clue = cluesRef.current.find(c => c.id === id);
    if (!clue || clue.type !== 'clue' || clue.verified === true) return;
    const caseId = clue.caseId;
    updateCluesAndCases(prev => prev.map(c => c.id === id ? { ...c, verified: true } : c));
    const caseInfo = casesRef.current.find(c => c.id === caseId);
    if (caseInfo) {
      const caseClues = cluesRef.current.filter(c => c.caseId === caseId).map(c => c.id === id ? { ...c, verified: true } : c);
      updateCaseEntry(caseId, caseInfo.name, caseClues, caseInfo.status === 'closed', caseInfo.closingStatement, caseInfo.origin);
    }
    addNotification('线索已坐实，归入已确立事实', 'success');
  }, [updateCluesAndCases]);

  const commitDeduction = useCallback((sourceClueIds: string[], text: string, caseId: string, position?: { x: number, y: number }, truth?: TruthTag, deductionType?: DeductionType) => {
    let posX = 200;
    let posY = 200;

    if (position) {
      posX = position.x;
      posY = position.y;
    } else if (sourceClueIds.length > 0) {
      // 取源素材位置的中下方
      const sourceClues = cluesRef.current.filter(c => sourceClueIds.includes(c.id));
      if (sourceClues.length > 0 && sourceClues[0].position) {
        posX = sourceClues.reduce((sum, c) => sum + (c.position?.x ?? 200), 0) / sourceClues.length;
        posY = Math.max(...sourceClues.map(c => c.position?.y ?? 200)) + 120;
      }
    }

    // 产出类型：源素材中含推断或推论 → 推论；全是线索 → 推断
    const sourceClues = sourceClueIds.length > 0
      ? cluesRef.current.filter(c => sourceClueIds.includes(c.id))
      : [];
    const hasHigherTier = sourceClues.some(c => c.type === 'inference' || c.type === 'deduction');
    const outputType: ClueType = hasHigherTier ? 'deduction' : 'inference';

    const newId = genId();
    const newClue: Clue = {
      id: newId,
      text,
      type: outputType,
      timestamp: getGameTimestamp(),
      source: sourceClueIds.length > 0 ? '逻辑推演' : '玩家手书',
      position: { x: posX, y: posY },
      caseId,
      sourceClueIds: sourceClueIds.length > 0 ? sourceClueIds : undefined,
      truth,
      deductionType: outputType === 'deduction' ? deductionType : undefined,
    };

    const newConnections = sourceClueIds.map(sid => [sid, newId] as [string, string]);
    updateCluesAndCases(
      prev => [...prev, newClue],
      prevConn => [...prevConn, ...newConnections],
    );

    // 同步到世界书
    const caseInfo = casesRef.current.find(c => c.id === caseId);
    if (caseInfo) {
      const caseClues = [...cluesRef.current.filter(c => c.caseId === caseId), newClue];
      updateCaseEntry(caseId, caseInfo.name, caseClues, caseInfo.status === 'closed', caseInfo.closingStatement, caseInfo.origin);
    }

    addNotification(outputType === 'deduction' ? '得出新推论' : '得出新推断', 'success');
  }, [updateCluesAndCases]);

  // ── NSFW CG 自动模式：按姿态名查 URL 替换背景 ──
  const triggerNsfwPose = useCallback((character: string, pose: string) => {
    const set = CHARACTER_IMAGES[character];
    // 无 NSFW 数据的角色（NPC 等）静默忽略
    if (!set?.nsfw) return;
    const found = set.nsfw.find(s => s.name === pose);
    if (!found) return; // 姿态名未命中，保持当前 CG 不变
    setNsfwCgUrl(found.url);
    console.info(`[NSFW] ${character} · ${pose}`);
  }, []);

  const resetNsfw = useCallback(() => {
    setNsfwCgUrl(null);
  }, []);

  // value 记忆化：函数引用稳定 + state 进 deps，state 未变时 value 不重建，
  // 避免无谓地触发所有 useGameContext 消费方重渲染。
  const contextValue = useMemo(() => ({
    currentScreen, setCurrentScreen, galleryTab, setGalleryTab,
    notifications, addNotification, removeNotification,
    clues, cases, addClue, verifyClue, removeClue, editClue, updateDeductionStatus, updateDeductionType, clueConnections, combineClues, commitDeduction,
    createCase, closeCase, reopenCase, renameCase, deleteCase, getCaseClues,
    isInvestigating, setIsInvestigating,
    isCombining,
    viewingFloorId, setViewingFloor, lastAssistantFloorId, isViewingHistory,
    isGenerating, generatingFloorId, startGenerating, finishGenerating,
    playerName, setPlayerName,
    pendingMessage, setPendingMessage,
    scriptCharacterLocations, setScriptCharacterLocations,
    gameTime, setGameTime,
    gameDateTime, setGameDateTime,
    weather, setWeather: (w: WeatherType) => {
      weatherRef.current = w;
      setWeatherState(w);
      ensureWeatherEntry(w).catch(e => {
        console.warn('[幻璃镜] 天象条目更新失败:', e);
      });
    },
    weatherLog,
    weatherParticlesEnabled, setWeatherParticlesEnabled,
    effectsEnabled, setEffectsEnabled,
    storyVersion,
    poolRegistry, ensurePoolBinding,
    evilRegistry, ensureEvilBinding,
    normalRegistry, ensureNormalBinding,
    nsfwCgUrl, triggerNsfwPose, resetNsfw,
  }), [
    currentScreen, galleryTab, notifications, clues, cases, clueConnections,
    isInvestigating, isCombining, viewingFloorId, lastAssistantFloorId,
    isGenerating, generatingFloorId, playerName, pendingMessage,
    scriptCharacterLocations, gameTime, gameDateTime, weather, weatherLog,
    weatherParticlesEnabled, effectsEnabled, storyVersion, poolRegistry, ensurePoolBinding,
    evilRegistry, ensureEvilBinding,
    normalRegistry, ensureNormalBinding,
    nsfwCgUrl, triggerNsfwPose, resetNsfw,
    renameCase,
  ]);

  return (
    <GameContext.Provider value={contextValue}>
      {children}
    </GameContext.Provider>
  );
};

/**
 * 轻量级选择性订阅 hook — 基于浅比较，避免不相关 state 变动引发重渲染。
 * 用法：const clues = useGameContext(c => c.clues);
 * 不传 selector 时退化为全量订阅（兼容旧代码）。
 */
export function useGameContext<T = GameContextProps>(selector?: (ctx: GameContextProps) => T): T {
  const context = useContext(GameContext);
  if (!context) {
    throw new Error('useGameContext must be used within a GameProvider');
  }
  // 无 selector 时全量返回
  if (!selector) return context as unknown as T;
  // 有 selector 时，用 ref + 浅比较避免不必要的重渲染
  const selected = selector(context);
  const ref = useRef(selected);
  if (!Object.is(ref.current, selected)) {
    ref.current = selected;
  }
  return ref.current;
}
