/**
 * 共享古风装饰组件 — 「琉璃绢梦」galgame 演出层
 * 全项目的「铜包角」「金线菱饰」「绢帛名牌」「朱印小签」以此为准。
 */
import React from 'react';
import { cn } from '../../utils';

interface OrnateCornersProps {
  /** 角饰边长，如 "w-8 h-8"（默认 w-8 h-8） */
  sizeCls?: string;
  /** 边框颜色类，如 "border-gold-400/60" */
  colorCls?: string;
  /** 是否叠加金漆呼吸光效 */
  glow?: boolean;
  className?: string;
}

/** 四角仿古铜包角（纯装饰，pointer-events 关闭） */
export const OrnateCorners: React.FC<OrnateCornersProps> = ({
  sizeCls = 'w-8 h-8',
  colorCls = 'border-gold-400/60',
  glow = false,
  className,
}) => (
  <>
    <div className={cn('absolute top-0 left-0 border-t-2 border-l-2 pointer-events-none', sizeCls, colorCls, glow && 'animate-ornate-glow', className)} />
    <div className={cn('absolute top-0 right-0 border-t-2 border-r-2 pointer-events-none', sizeCls, colorCls, className)} />
    <div className={cn('absolute bottom-0 left-0 border-b-2 border-l-2 pointer-events-none', sizeCls, colorCls, className)} />
    <div className={cn('absolute bottom-0 right-0 border-b-2 border-r-2 pointer-events-none', sizeCls, colorCls, className)} />
  </>
);

/** 古典金线分隔线：中段金色渐显、两端隐入墨色 */
export const InkDivider: React.FC<{ className?: string }> = ({ className }) => (
  <div className={cn('w-full h-px bg-linear-to-r from-transparent via-gold-500/40 to-transparent shrink-0', className)} />
);

/** 金线菱饰边：细金双线夹一枚菱珠 — 视觉小说文本框顶缘专用 */
export const DiamondEdge: React.FC<{ className?: string }> = ({ className }) => (
  <div aria-hidden className={cn('vn-edge', className)} />
);

interface NamePlateProps {
  /** 角色主题色：朱（默认）或 青 */
  theme?: 'vermilion' | 'cyan';
  /** 名牌文字（含作者/玩家名替换后的显示名） */
  name: React.ReactNode;
  /** 情绪小签，如 "浅笑"（空则不显示） */
  emotion?: string;
  /** 头像 URL（可选，圆角方形小像） */
  avatar?: string;
  size?: 'sm' | 'md';
  className?: string;
}

/**
 * 绢帛名牌 — galgame 说话人铭牌。
 * 漆底金线 + 毛笔楷书 + 角色主题色釉光，直立无倾斜。
 */
export const NamePlate: React.FC<NamePlateProps> = ({
  theme = 'vermilion', name, emotion, avatar, size = 'md', className,
}) => {
  const accent = theme === 'cyan' ? 'rgba(98, 181, 181, 0.55)' : 'rgba(223, 86, 69, 0.5)';
  const textSize = size === 'sm' ? 'text-base sm:text-lg' : 'text-xl sm:text-2xl';
  return (
    <span
      className={cn('nameplate rounded-xs py-1 px-3 sm:px-4', textSize, className)}
      style={{ '--plate-accent': accent, '--plate-glow': theme === 'cyan' ? 'rgba(50,135,135,0.28)' : 'rgba(207,58,44,0.22)' } as React.CSSProperties}
    >
      {avatar && (
        <img
          src={avatar}
          alt=""
          className={cn('object-cover object-top rounded-[2px] border', size === 'sm' ? 'w-6 h-6' : 'w-8 h-8 sm:w-9 sm:h-9', theme === 'cyan' ? 'border-cyan-700/80' : 'border-vermilion-700/80')}
          loading="eager"
        />
      )}
      <span className={theme === 'cyan' ? 'text-cyan-300' : 'text-paper-100'} style={theme === 'vermilion' ? { color: 'var(--color-paper-100)' } : undefined}>
        {name}
      </span>
      {emotion && emotion !== '默认' && (
        <span className={cn(
          'not-italic font-sans tracking-normal opacity-75 border px-1 rounded-[2px]',
          size === 'sm' ? 'text-[10px]' : 'text-xs',
          theme === 'cyan' ? 'text-cyan-300/80 border-cyan-700/60' : 'text-paper-300/80 border-gold-750/80',
        )}>
          {emotion}
        </span>
      )}
    </span>
  );
};

/** 朱印小签 — 旁白/状态标记 */
export const NarratorSeal: React.FC<{ label?: string; className?: string }> = ({ label = '旁白', className }) => (
  <span aria-hidden className={cn('narrator-seal text-[10px] rounded-[2px]', className)}>{label}</span>
);
