import React, { useEffect, useState, useRef, useMemo } from 'react';
import { useGameContext, type ClueSource, CLUES_PER_FLOOR } from '../../store/GameContext';
import { Box, MapPin, Users, ScrollText } from 'lucide-react';

/** 收录来源四类：勘验/文书为硬证据即坐实；证言/传闻为软信息，须坐实后方可按事实引用 */
const SOURCE_OPTIONS: { key: ClueSource; icon: React.FC<{ size?: number; className?: string }>; hint: string }[] = [
  { key: '勘验', icon: Box, hint: '亲验所得，立为事实' },
  { key: '证言', icon: Users, hint: '问话所得，待证' },
  { key: '文书', icon: ScrollText, hint: '档册信函，立为事实' },
  { key: '传闻', icon: MapPin, hint: '市井之言，待证' },
];

export const TextSelectionClue: React.FC = () => {
  const addClue = useGameContext(c => c.addClue);
  const isInvestigating = useGameContext(c => c.isInvestigating);
  const cases = useGameContext(c => c.cases);
  const clues = useGameContext(c => c.clues);
  const lastAssistantFloorId = useGameContext(c => c.lastAssistantFloorId);
  const [selectionRect, setSelectionRect] = useState<DOMRect | null>(null);
  const [selectedText, setSelectedText] = useState('');
  const [picking, setPicking] = useState(false);
  const popoverRef = useRef<HTMLDivElement>(null);

  // 本幕已收录线索数
  const floorClueCount = useMemo(() => {
    if (lastAssistantFloorId == null) return 0;
    return clues.filter(c => c.floorId === lastAssistantFloorId && c.type === 'clue').length;
  }, [clues, lastAssistantFloorId]);

  const quotaLeft = CLUES_PER_FLOOR - floorClueCount;
  const quotaExhausted = quotaLeft <= 0;

  useEffect(() => {
    if (!isInvestigating) {
      setSelectionRect(null);
      setSelectedText('');
      return;
    }

    let timeoutId: ReturnType<typeof setTimeout>;
    
    const handleSelectionChange = () => {
      clearTimeout(timeoutId);
      timeoutId = setTimeout(() => {
        const selection = window.getSelection();
        if (selection && !selection.isCollapsed && selection.toString().trim().length > 0) {
          const text = selection.toString().trim();
          const range = selection.getRangeAt(0);
          const rect = range.getBoundingClientRect();
          
          if (rect.width > 0 && rect.height > 0) {
            setSelectedText(text);
            setSelectionRect(rect);
          }
        } else {
          setSelectionRect(null);
          setSelectedText('');
        }
      }, 100);
    };

    const handleMouseUp = (e: MouseEvent | TouchEvent) => {
      if (popoverRef.current && popoverRef.current.contains(e.target as Node)) {
        return;
      }
      handleSelectionChange();
    };

    const handleScroll = () => {
      setSelectionRect(null);
      setSelectedText('');
    };

    document.addEventListener('selectionchange', handleSelectionChange);
    document.addEventListener('mouseup', handleMouseUp);
    document.addEventListener('touchend', handleMouseUp);
    window.addEventListener('scroll', handleScroll, true);

    return () => {
      clearTimeout(timeoutId);
      document.removeEventListener('selectionchange', handleSelectionChange);
      document.removeEventListener('mouseup', handleMouseUp);
      document.removeEventListener('touchend', handleMouseUp);
      window.removeEventListener('scroll', handleScroll, true);
    };
  }, [isInvestigating]);

  if (!selectionRect || !selectedText || !isInvestigating) return null;

  const handleAddClue = (category: ClueSource) => {
    // 场面制：本幕配额已满时拒绝收录
    if (quotaExhausted) {
      return;
    }
    // 查找当前活跃案件
    const activeCase = cases.find(c => c.status === 'active');
    if (!activeCase) {
      addClue(selectedText, `玩家收集·${category}`, '_temp', undefined, undefined, category);
    } else {
      addClue(selectedText, `玩家收集·${category}`, activeCase.id, undefined, undefined, category);
    }
    setSelectionRect(null);
    setSelectedText('');
    setPicking(false);
    window.getSelection()?.removeAllRanges();
  };

  return (
    <div
      ref={popoverRef}
      className="fixed z-[1000] animate-in fade-in zoom-in duration-200 pointer-events-auto"
      style={{
        top: Math.max(10, selectionRect.top - 50),
        left: selectionRect.left + selectionRect.width / 2,
        transform: 'translateX(-50%)',
      }}
    >
      {!picking ? (
        <div className="flex items-center bg-ink-900 border border-gold-500/50 rounded shadow-lg shadow-black/50 overflow-hidden">
          <button
            onClick={() => setPicking(true)}
            disabled={quotaExhausted}
            className="flex items-center gap-2 px-4 py-2 hover:bg-ink-800 transition-colors group disabled:opacity-40 disabled:cursor-not-allowed"
          >
            <Box size={14} className="text-gold-400 opacity-70 group-hover:opacity-100 transition-opacity" />
            <span className="font-sans text-xs tracking-widest text-paper-200 whitespace-nowrap">
              {quotaExhausted ? '此景已尽' : '收集线索'}
            </span>
          </button>
          <div className="flex items-center gap-1 px-2.5 py-2 border-l border-gold-850">
            <span className="font-sans text-[10px] tracking-wider text-paper-500 whitespace-nowrap">
              本幕 {floorClueCount}/{CLUES_PER_FLOOR}
            </span>
          </div>
        </div>
      ) : quotaExhausted ? (
        <div className="bg-ink-900 border border-gold-500/50 rounded shadow-lg shadow-black/50 p-3 max-w-[200px]">
          <div className="font-serif text-xs text-paper-300 leading-relaxed">
            此景已尽力记下，再查须待新事态。
          </div>
          <button
            onClick={() => { setPicking(false); setSelectionRect(null); setSelectedText(''); }}
            className="mt-2 font-sans text-[10px] tracking-widest text-paper-500 hover:text-paper-300 transition-colors"
          >
            知道了
          </button>
        </div>
      ) : (
        <div className="bg-ink-900 border border-gold-500/50 rounded shadow-lg shadow-black/50 p-2">
          <div className="flex items-center justify-between px-1 pb-1.5">
            <span className="font-sans text-[10px] tracking-widest text-paper-400">此线索记为何来？</span>
            <span className="font-sans text-[9px] tracking-wider text-paper-600">余 {quotaLeft} 条</span>
          </div>
          <div className="grid grid-cols-2 gap-1">
            {SOURCE_OPTIONS.map(({ key, icon: Icon, hint }) => (
              <button
                key={key}
                title={hint}
                onClick={() => handleAddClue(key)}
                className="flex items-center gap-1.5 px-2.5 py-1.5 bg-ink-800 hover:bg-ink-700 border border-gold-850 hover:border-gold-500 rounded transition-colors"
              >
                <Icon size={13} className="text-gold-400" />
                <span className="font-serif text-xs text-paper-200 whitespace-nowrap">{key}</span>
              </button>
            ))}
          </div>
          <div className="font-sans text-[9px] text-paper-600 px-1 pt-1">证言/传闻为待证，须印证后按事实引用</div>
        </div>
      )}
    </div>
  );
};
