export type PoolSceneType = 'indoor' | 'outdoor';

export interface PoolScene {
  type: PoolSceneType;
  /** 气质描述 (结构.txt 原文, 供先抽后演回注) */
  desc: string;
  /** 图片变体: outdoor=晴阴雪×昼夜, indoor=昼/夜 */
  variants: Record<string, string>;
}

export interface PoolAsset {
  name: string;
  tier: string;
  scenes: Record<string, PoolScene>;
}

export interface PoolTierMeta {
  label: string;
  /** 预绑大区 (REALM_REGIONS.name) */
  region: string;
  /** 预绑坊区 (该大区下的分区名, 匹配不到时落在大区第一个分区) */
  area: string;
  /** 是否进洗牌袋 (限时池不进) */
  inBag: boolean;
}

