/**
 * 教程引导气泡 — 轻量浮动提示，不阻断操作
 *
 * pointer-events 分区：气泡本身可交互（按钮可点），
 * 但遮罩层 pointer-events-none 不遮挡下方文本。
 */

import React from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { Lightbulb, X } from 'lucide-react';
import { TUTORIAL_STEPS, type TutorialStep } from '../../hooks/useTutorial';
import { cn } from '../../utils';

interface TutorialBubbleProps {
  activeStep: TutorialStep | null;
  onDismiss: () => void;
  /** 锚定位置：'top' 浮于文本区上方，'bottom' 浮于文本区下方 */
  position?: 'top' | 'bottom';
}

export const TutorialBubble: React.FC<TutorialBubbleProps> = ({
  activeStep,
  onDismiss,
  position = 'top',
}) => {
  return (
    <AnimatePresence>
      {activeStep != null && (
        <motion.div
          key={`tutorial-${activeStep}`}
          initial={{ opacity: 0, y: position === 'top' ? -12 : 12, scale: 0.92 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={{ opacity: 0, y: position === 'top' ? -8 : 8, scale: 0.95 }}
          transition={{ type: 'spring', damping: 24, stiffness: 320 }}
          className={cn(
            'absolute left-1/2 -translate-x-1/2 z-60 pointer-events-auto',
            'max-w-[90%] sm:max-w-md',
            position === 'top' ? 'bottom-full mb-3' : 'top-full mt-3',
          )}
        >
          {/* 小三角指示器 */}
          <div
            className={cn(
              'absolute left-1/2 -translate-x-1/2 w-0 h-0',
              'border-l-[7px] border-r-[7px] border-transparent',
              position === 'top'
                ? 'top-full border-t-[7px] border-t-ink-800'
                : 'bottom-full border-b-[7px] border-b-ink-800',
            )}
          />

          <div className="bg-ink-800/97 backdrop-blur-md border border-gold-600/70 rounded-xs shadow-2xl overflow-hidden">
            {/* 标题栏 */}
            <div className="flex items-center justify-between px-3.5 py-2 bg-ink-750 border-b border-gold-850/60">
              <div className="flex items-center gap-1.5">
                <Lightbulb className="w-3.5 h-3.5 text-gold-400" />
                <span className="font-serif text-xs font-bold tracking-widest text-gold-300">
                  {TUTORIAL_STEPS[activeStep].title}
                </span>
                <span className="text-[9px] text-paper-500 font-sans ml-1">
                  引导 {activeStep + 1}/6
                </span>
              </div>
              <button
                onClick={onDismiss}
                className="text-paper-400 hover:text-vermilion-400 transition-colors p-0.5"
                title="跳过"
              >
                <X className="w-3.5 h-3.5" />
              </button>
            </div>
            {/* 正文 */}
            <div className="px-3.5 py-2.5">
              <p className="text-xs font-serif text-paper-200/90 leading-relaxed tracking-wide">
                {TUTORIAL_STEPS[activeStep].body}
              </p>
            </div>
            {/* 底部操作 */}
            <div className="flex justify-end px-3.5 pb-2.5">
              <button
                onClick={onDismiss}
                className="btn-gu btn-gu-primary px-3 py-1 text-[10px] font-serif font-bold tracking-widest"
              >
                知 道 了
              </button>
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};
